const top_teemo = {
  champion: '티모',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (E)\'맹독 다트\'의 독 피해를 꾸준히 묻히며 가렌의 (Q)\'결정타\'가 닿지 않는 거리를 유지하세요. 가렌이 (Q)\'결정타\'로 달려들면 (Q)\'실명 다트\'를 사용해 공격을 막거나 (W)\'신속한 이동\'으로 거리를 벌리며 피해를 최소화해요. 가렌의 (P)\'인내심\' 회복을 막으려면 계속해서 평타를 섞어 피해를 입히는 게 좋아요.', lv3: '가렌이 (E)\'심판\'으로 회전하며 달려들 때는 (Q)\'실명 다트\'로 회전 피해를 막을 수 없으니 (W)\'신속한 이동\'으로 회전 범위에서 벗어나고, (Q)\'결정타\' 강화 평타를 쓰려 할 때 (Q)\'실명 다트\'를 맞혀 빗나가게 하세요. 가렌이 (W)\'용기\'를 사용해 보호막을 얻었다면 무리하게 싸우지 말고 거리를 두며 (E)\'맹독 다트\'의 독 피해로 견제만 해요. 가렌의 (Q)\'결정타\' 침묵에 걸리면 스킬을 쓸 수 없으니 가렌이 (Q)\'결정타\'를 쓰기 전에 미리 거리를 조절하세요.', lv6: '가렌이 (R)\'데마시아의 정의\'로 마무리할 수 있는 체력이 되지 않도록 항상 라인 위치를 관리하세요. (Q)\'결정타\'는 걸려 있는 둔화를 모두 제거하니 (R)\'유독성 함정\'의 둔화에만 기대지 말고 침묵에 걸리기 전에 거리를 벌려 두세요. 정글러가 오면 가렌이 (Q)\'결정타\'로 빠르게 붙을 수 있으니 (R)\'유독성 함정\'으로 접근 방향을 미리 확인하세요.', item: '첫 코어로 리안드리의 고통을 선택해 (E)\'맹독 다트\'의 독 피해와 시너지를 내며 지속적인 피해를 입히세요. 신발은 가렌의 (Q)\'결정타\' 기본 공격 피해를 줄여 주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하면 체력이 낮은 가렌을 잡기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 골드를 챙기려 하니 미니언 근처에서 (Q)\'실명 다트\'를 활용해 견제하세요. (E)\'맹독 다트\'를 맞춘 뒤 평타를 섞어 독 피해를 쌓되, (P)\'불의 심판\' 때문에 너무 오래 붙어있지 마세요.', lv3: '갱플랭크가 설치한 (E)\'화약통\' 근처에서는 폭발 피해를 입을 수 있으니 주의하며 거리를 조절하세요. (W)\'괴혈병 치료\'를 먼저 사용하게 유도한 뒤 (Q)\'실명 다트\'를 맞추어 딜교환을 이어가세요.', lv6: '이동 경로에 (R)\'유독성 함정\'을 설치해 갱플랭크의 움직임을 늦추고 피해를 입히세요. (R)\'포탄 세례\'에 맞으면 둔화가 걸리니 위치 선정에 유의하며 라인을 당겨서 관리하세요. 정글러의 개입에 대비해 버섯으로 주변 시야를 확보하세요.', item: '리안드리의 고통과 판금 장화를 선택하세요. 리안드리의 고통으로 지속적인 마법 피해를 입히고, 판금 장화로 갱플랭크의 기본 공격 피해를 줄여요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄여서 킬을 노리세요.' },
    '그라가스': { lv1: '그라가스가 (Q)\'술통 굴리기\'로 둔화와 견제를 넣으려 하니 술통이 터지는 위치를 피해 막타를 챙기세요. (W)\'신속한 이동\'을 활용해 거리를 조절하며 (E)\'맹독 다트\'를 적중시켜 지속적인 피해를 입히세요. 초반에는 무리하게 맞서기보다 (Q)\'실명 다트\'로 적의 공격을 견제하며 버티는 것이 좋아요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 돌진하면 맞은 적이 공중에 떠 스킬을 쓸 수 없으니 돌진 방향이 보이면 옆으로 벗어나세요. 그라가스가 (W)\'취중 분노\'를 켜고 강화 평타를 쓰려 할 때 (Q)\'실명 다트\'를 맞히면 평타를 빗나가게 할 수 있어요. (E)\'몸통 박치기\'가 빠진 뒤에 (E)\'맹독 다트\'를 묻히며 짧게 딜교환을 하고 빠지세요.', lv6: '그라가스의 (R)\'술통 폭발\'은 폭발 지점에서 적을 밀어내니 그라가스나 정글러 쪽으로 밀려나지 않도록 위치를 잡아야 해요. 그라가스가 진입하려는 경로에 (R)\'유독성 함정\'을 미리 깔아두면 둔화와 피해를 동시에 줄 수 있어요. 적의 체력이 낮을 때 (R)\'유독성 함정\'으로 마무리 각을 보며 킬을 노려보세요.', item: '리안드리의 고통을 첫 코어로 올려 (E)\'맹독 다트\'의 지속 피해를 극대화하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'술통 폭발\'로 거리가 벌어졌을 때 점멸로 따라붙기 좋고 점화로 킬각을 잡기 편해요.' },
    '그웬': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 활용하여 그웬이 가까이 오지 못하게 꾸준히 견제하며 거리를 유지하세요. 그웬이 (Q)\'싹둑싹둑!\'의 범위 안으로 들어오려고 하면 (W)\'신속한 이동\'을 써서 빠르게 거리를 벌려야 해요. 초반에는 근접해서 싸우기보다 원거리에서 피해를 입히는 데 집중하는 것이 좋아요.', lv3: '그웬이 (E)\'돌격가위\'로 돌진하며 평타를 치려 할 때 (Q)\'실명 다트\'를 맞히면 (P)\'가위 난도질\'의 피해를 효과적으로 줄일 수 있어요. 그웬이 (W)\'신성한 안개\'를 사용하면 안개 밖에서는 대상을 지정할 수 없으니 무리하게 진입하지 말고 뒤로 물러나세요. 그웬의 스킬이 빠진 뒤에 다시 (E)\'맹독 다트\'로 압박하며 딜교환을 이어가세요.', lv6: '그웬이 (R)\'바느질\'로 바늘을 던질 때는 둔화에 걸리지 않도록 궤적에서 벗어나 움직이세요. 그웬이 (W)\'신성한 안개\' 속에서 (Q)\'싹둑싹둑!\'을 쓰며 밀고 들어오면 (R)\'유독성 함정\'을 밟게 해 둔화시키세요. (Q)\'실명 다트\'로 그웬의 평타를 방해하고 버섯으로 정글러의 위치를 확인하며 라인을 관리하세요.', item: '첫 코어 아이템은 리안드리의 고통을 가고 신발은 헤르메스의 발걸음을 선택하세요. 리안드리의 고통은 지속 피해를 입히기 좋고 헤르메스의 발걸음은 그웬의 마법 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 그웬의 (P)\'가위 난도질\' 회복을 억제해야 적을 마무리하기 쉬워요.' },
    '나르': { lv1: '(Q)\'부메랑 던지기\'의 궤적에서 벗어나 맞지 않도록 주의하며 (E)\'맹독 다트\'로 지속적인 피해를 입히세요. 나르가 평타를 치러 다가오면 (Q)\'실명 다트\'를 사용해 나르의 공격을 무효화하며 거리를 벌리세요. 첫 웨이브부터 계속해서 평타 견제를 이어가며 체력을 깎아두는 게 중요해요.', lv3: '나르가 (E)\'폴짝\'으로 순식간에 거리를 좁히며 들어올 때 (W)\'신속한 이동\'을 켜서 빠르게 도망치세요. (W)\'슝슝\'의 세 번째 공격 추가 피해를 입지 않도록 짧게 치고 빠지는 딜교환을 반복하세요. 나르가 부메랑을 던진 후 다시 받기 전까지의 빈틈을 노려 평타 견제를 집중하세요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절하므로 벽 근처에 서 있지 말고 넓은 공간으로 이동하세요. 나르가 변신하여 다가오는 경로에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추고 접근을 방해하세요. 메가 나르의 (W)\'쿵쾅\' 기절 범위를 피해 옆으로 무빙하며 정글러가 올 때까지 버티는 게 좋아요.', item: '리안드리의 고통으로 체력이 높은 메가 나르에게 지속 피해를 입히세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 나르의 체력을 빠르게 깎아 킬각을 잡기 위해 점화의 추가 피해가 필요해요.' },
    '나서스': { lv1: '나서스는 초반에 (Q)\'흡수의 일격\' 스택을 쌓는 데 집중하므로 상대적으로 몸싸움이 약한 구간이에요. (Q)\'실명 다트\'와 (E)\'맹독 다트\'를 활용해 계속해서 견제하며 나서스가 미니언을 편하게 먹지 못하게 하세요. 나서스가 (Q)\'흡수의 일격\'을 쓰며 다가오면 거리를 벌려 피해를 최소화해야 해요.', lv3: '(W)\'쇠약\'은 이동 속도와 공격 속도를 점진적으로 늦추니 오래 맞지 않도록 거리를 조절하세요. 나서스가 (Q)\'흡수의 일격\'을 강화 평타로 쓰려 할 때 (Q)\'실명 다트\'를 맞혀 평타를 빗나가게 하세요. (W)\'신속한 이동\'으로 접근을 피하며 (E)\'맹독 다트\'의 지속 피해를 입히세요.', lv6: '(R)\'사막의 분노\'가 켜진 나서스는 체력이 늘어나고 주변에 피해를 주니 폭풍 안에서는 싸우지 마세요. (R)\'유독성 함정\'을 길목에 깔아 나서스의 이동을 방해하고 미니언을 챙기기 어렵게 만드세요. 나서스가 궁극기를 사용하면 거리를 두고 버티며 지속시간이 끝나기를 기다려야 해요.', item: '체력이 많은 나서스에게 지속 피해를 입히기 위해 리안드리의 고통을 먼저 올리세요. 신발은 나서스의 (Q)\'흡수의 일격\' 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 체력 회복을 줄이고 초반에 압박을 가하세요.' },
    '녹턴': { lv1: '(E)\'맹독 다트\'와 (Q)\'실명 다트\'를 사용하여 거리를 유지하며 꾸준히 견제하세요. 녹턴이 (Q)\'황혼의 인도자\'를 던지며 접근할 때는 미니언 뒤에 숨기보다 옆으로 비껴서 피해야 해요. 초반부터 체력을 깎아두어야 녹턴이 쉽게 진입하지 못해요.', lv3: '녹턴이 (W)\'어둠의 장막\'으로 스킬을 막으려 할 수 있으니 주의하며 딜교환을 하세요. (E)\'말할 수 없는 공포\'는 대상과 연결되는 스킬이라 걸어서 피할 수 없으니 연결되면 (W)\'신속한 이동\'으로 사거리 밖으로 벗어나 공포를 끊어야 해요. 상대의 (W)\'어둠의 장막\'이 빠진 것을 확인하고 (Q)\'실명 다트\'를 맞춰 상대의 공격을 방해하세요.', lv6: '녹턴이 (R)\'피해망상\'으로 시야를 가리고 돌진할 때 발밑에 (R)\'유독성 함정\'을 설치하여 대응하세요. 함정의 둔화로 녹턴의 접근을 늦추고 정글러의 개입을 미리 대비해야 해요. 시야가 사라지면 라인을 너무 밀지 말고 (R)\'유독성 함정\'을 깔며 조심스럽게 플레이하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 녹턴의 기본 공격 피해를 줄여주고 리안드리의 고통은 (E)\'맹독 다트\'와 함께 적에게 지속적인 피해를 줘요.', spell: '점멸과 점화를 추천해요. 점멸은 녹턴의 돌진에 대응하기 좋고 점화는 상대의 체력 회복을 억제하며 킬을 노리기 좋아요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓이면 평타가 매우 강력해지니 1~2레벨 구간에는 최대한 거리를 유지하며 (Q)\'실명 다트\'로 견제하세요. (Q)\'학살\'의 도끼날에 맞으면 체력을 회복하며 큰 피해를 입히니 날 끝에 맞지 않도록 주의하며 거리 조절을 해야 해요.', lv3: '다리우스가 (E)\'포획\'을 사용하여 끌어당기려 할 때 (W)\'신속한 이동\'을 사용해 거리를 벌리며 대응하세요. (Q)\'실명 다트\'를 사용하여 다리우스의 평타를 막는 동시에 (E)\'맹독 다트\'를 묻히고 빠르게 뒤로 빠지는 것이 중요해요. (W)\'마비의 일격\'에 맞으면 이동 속도가 줄어드니 주의하며 스킬을 맞춰서 교환하세요.', lv6: '다리우스가 (R)\'녹서스의 단두대\'를 사용하기 전에 (R)\'유독성 함정\'을 미리 설치하여 다리우스의 진입을 방해하세요. (P)\'과다출혈\' 중첩이 높을 때는 다리우스의 킬각이 매우 강력하니 무리하게 싸우지 말고 라인을 당기며 정글러의 도움을 기다려야 해요. 다리우스가 (E)\'포획\'으로 끌어당기면 공중에 떠 스킬을 쓸 수 없으니 (E)\'포획\'을 쓰기 전에 거리를 벌려 두세요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 마법 피해를 입히고 신발은 물리 피해를 줄여주는 판금 장화를 선택하세요. 이 조합으로 다리우스의 물리 피해를 견디며 마법 피해를 누적시켜요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 진입하거나 (R)\'녹서스의 단두대\'로 몰아칠 때 탈진을 걸어 피해량을 줄이세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'로 멀리서 견제하지만 1~2레벨에는 스킬이 적어 티모가 압박하기 좋아요. (E)\'맹독 다트\'를 묻히고 평타를 섞으며 괴롭히고 라이즈의 (Q)\'과부하\'는 미니언 뒤에 서서 피하세요. (W)\'신속한 이동\'을 활용해 라이즈와의 거리를 조절하며 견제하세요.', lv3: '라이즈가 (E)\'주문 전이\' 표식을 남긴 상태에서 (W)\'룬 감옥\'을 사용하면 속박되니 조심하세요. 라이즈의 (W)\'룬 감옥\'이 빠진 타이밍에 (Q)\'실명 다트\'를 맞춰 딜교환을 시도하는 것이 좋아요. (E)\'맹독 다트\' 효과를 유지하며 평타를 섞어 라이즈의 체력을 깎으세요.', lv6: '라이즈가 (R)\'공간 왜곡\'으로 아군을 합류시킬 수 있으니 차원문이 열리면 정글러의 개입에 대비해 라인을 너무 밀지 마세요. 라이즈가 (W)\'룬 감옥\'으로 다가올 때는 (Q)\'실명 다트\'를 맞혀 평타 피해를 줄이세요. 라이즈의 접근 경로에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추세요.', item: '내셔의 이빨을 첫 코어로 선택하여 공격 속도와 주문력을 모두 높이세요. 신발은 라이즈의 마법 피해를 견디기 위해 헤르메스의 발걸음을 구매하세요.', spell: '점멸과 점화를 추천해요. 라이즈가 (W)\'룬 감옥\'으로 속박하기 전에 점화로 빠르게 체력을 깎아 킬을 노리세요.' },
    '럼블': { lv1: '럼블이 (Q)\'화염방사기\'로 근접해서 공격하면 피해가 강력하니 사거리 밖에서 거리를 유지하세요. (E)\'맹독 다트\'로 멀리서 견제하세요. (W)\'신속한 이동\'을 적절히 사용하여 럼블의 사정권에서 빠르게 벗어나세요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하여 피해를 흡수할 때는 무리한 딜교환을 피하세요. 럼블의 열기가 높아져 기본 공격을 섞을 때 (Q)\'실명 다트\'를 맞히면 평타 피해를 차단할 수 있어요. (E)\'전기 작살\'에 맞으면 마법 저항력이 낮아지니 주의하며 싸우세요.', lv6: '럼블의 (R)\'이퀄라이저 미사일\'이 깔리면 불타는 궤적을 피해 즉시 옆으로 이동하세요. 럼블이 궁극기를 사용한 뒤의 빈틈을 노려 (R)\'유독성 함정\'을 설치하며 압박하세요. 럼블의 궁극기는 정글러와 함께 쓰기 좋으니 라인 관리에 신경 써야 해요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 강화하세요. 신발은 럼블의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 체력이 낮아진 럼블을 마무리하기 좋아요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반 교전에 강하니 거리를 멀리 유지하세요. (E)\'맹독 다트\'를 활용해 꾸준히 견제하며 레넥톤이 미니언을 편하게 챙기지 못하게 해야 해요. 1~2레벨에는 무리한 싸움보다 거리 조절에 집중하며 버티는 것이 좋아요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 (Q)\'실명 다트\'를 미리 사용하여 (W)\'무자비한 포식자\'의 기본 공격 피해와 기절 연계를 방해하세요. 레넥톤의 분노가 높을 때는 (W)\'무자비한 포식자\'의 기절 시간이 길어지니 주의해야 해요. 딜교환 이후에는 (W)\'신속한 이동\'을 사용해 빠르게 거리를 벌리며 안전하게 빠지세요.', lv6: '레넥톤이 (R)\'강신\'을 사용하면 체력이 늘어나고 매우 단단해지니 정면 대결을 피하세요. 레넥톤이 들어오는 경로에 (R)\'유독성 함정\'을 미리 설치하여 이동을 방해하고 피해를 입혀야 해요. 레넥톤의 궁극기 효과가 끝난 뒤에 다시 견제를 시작하며 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 마법 피해를 입히세요. 신발은 레넥톤의 물리 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\'을 통한 체력 회복 효과를 감소시킬 수 있어요.' },
    '렝가': { lv1: '수풀 근처에 가지 말고 거리 조절을 하며 (E)\'맹독 다트\'로 계속 견제하세요. (P)\'보이지 않는 포식자\'의 도약은 미니언이 막아 주지 않으니 수풀에서 멀리 떨어져 거리를 유지하세요. 초반에는 거리만 잘 유지해도 편하게 라인전을 시작할 수 있어요.', lv3: '렝가의 (E)\'올가미 투척\'은 야성이 최대일 때만 속박하고 평소에는 둔화시키니 (W)\'신속한 이동\'으로 거리를 유지하세요. 렝가가 도약해 들어오는 순간 (Q)\'실명 다트\'를 사용해 (Q)\'포악함\'의 강력한 물리 피해를 빗나가게 하는 것이 핵심이에요. 상대의 스킬이 빠진 뒤에 짧게 딜교환을 하고 뒤로 빠지세요.', lv6: '상대가 (R)\'사냥의 전율\'로 위장해 접근할 때 (R)\'유독성 함정\'을 밟게 하여 위치를 드러내고 이동 속도를 늦추세요. 버섯의 둔화 효과를 이용해 거리 조절을 하며 정글러의 개입에 대비하는 것이 중요해요. 렝가의 방어력 감소 효과가 적용된 상태에서는 평타 교전이 위험하니 주의하세요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화의 기본 공격 피해 감소 효과로 상대의 폭발적인 피해를 줄이고 내셔의 이빨로 공격 속도를 높여 지속 피해를 입히세요.', spell: '점멸과 탈진을 추천해요. 렝가가 도약해 들어왔을 때 탈진을 사용해 입히는 피해량을 줄이고 둔화시켜 생존 확률을 높이세요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용해 빠르게 접근하며 (P)\'룬 검\' 추가 피해를 노리니 거리를 유지해야 해요. 1~2레벨에는 (E)\'맹독 다트\'로 멀리서 체력을 깎으며 리븐의 진입을 방해하세요. 리븐이 다가올 때 (W)\'신속한 이동\'을 써서 거리를 벌리는 것이 중요해요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞으면 위험하니 스킬이 빠진 것을 확인하고 교환을 시작하세요. 리븐이 (P)\'룬 검\'을 활용해 평타를 치려 할 때 (Q)\'실명 다트\'를 맞히면 피해를 줄일 수 있어요. (E)\'용맹\'의 보호막이 유지되는 동안에는 무리하게 맞서지 말고 기다려주세요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용해 사거리가 길어지면 (R)\'유독성 함정\'을 진입 경로에 깔아 이동 속도를 늦추세요. 리븐이 들어올 때는 (Q)\'실명 다트\'를 아껴두었다가 적절한 타이밍에 사용해야 해요. 라인 관리를 잘하면서 정글러의 도움을 받아 리븐을 압박하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 입히세요. 신발은 리븐의 물리 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮을 때 점화로 마무리 피해를 더할 수 있어요.' },
    '리산드라': { lv1: '리산드라가 (Q)\'얼음 파편\'으로 견제할 때 거리를 조절하며 (Q)\'실명 다트\'를 던져 대응하세요. (E)\'맹독 다트\'를 적중시켜 독 피해를 누적하며 리산드라의 체력을 미리 깎아두는 것이 중요해요.', lv3: '리산드라가 (W)\'서릿발\'을 쓰기 전에 거리를 벌려 속박 범위에 들어가지 마세요. (W)\'서릿발\'이 빠진 타이밍에 (Q)\'실명 다트\'를 맞히고 (E)\'맹독 다트\'의 피해를 누적시키며 딜교환을 하세요.', lv6: '리산드라가 (R)\'얼음 무덤\'을 자신에게 사용해 무적 상태가 되면 공격을 멈추고 기다리세요. (E)\'얼음갈퀴 길\'로 들어오는 길목에 (R)\'유독성 함정\'을 설치해 리산드라의 진입을 방해해요.', item: '구인수의 격노검을 첫 코어로 올려 (E)\'맹독 다트\'의 효과를 극대화하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절이나 (W)\'서릿발\' 속박을 정화로 풀어낼 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 마스터 이의 (P)\'2연속 공격\'이 닿지 않는 거리에서 (E)\'맹독 다트\'로 견제하며 체력을 깎아두세요. 마스터 이가 (Q)\'일격 필살\'로 빠르게 접근하면 (W)\'신속한 이동\'을 사용하여 거리를 벌리는 것이 좋아요.', lv3: '마스터 이가 평타를 치러 올 때 (Q)\'실명 다트\'를 맞혀 기본 공격이 빗나가게 하세요. 마스터 이가 (W)\'명상\'을 사용하여 체력을 회복하려고 하면 딜교환을 멈추고 뒤로 물러나세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 (R)\'유독성 함정\'의 둔화 효과가 적용되지 않으니 주의해야 해요. 마스터 이가 진입할 때 (Q)\'실명 다트\'를 사용하여 평타를 빗나가게 하고 (R)\'유독성 함정\'의 피해로 압박하세요. (R)\'최후의 전사\' 중에도 (R)\'유독성 함정\'의 피해와 위치 드러내기는 적용되니 정글러가 올 길목에 버섯을 미리 깔아두세요.', item: '첫 코어 아이템으로 리안드리의 고통을 선택하여 지속적인 마법 피해를 입히세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복할 때 점화로 그 효과를 줄여야 해요.' },
    '마오카이': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 사용하여 원거리에서 마오카이의 체력을 깎으며 견제하세요. 마오카이가 (Q)\'덤불 주먹\'을 써서 뒤로 밀어내고 둔화를 걸며 다가오면 거리를 벌려야 해요. (P)\'마법 흡수\'가 준비된 평타는 체력을 회복시키니 마오카이가 붙으면 평타 교환을 길게 하지 마세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진해 속박하는 동안에는 마오카이를 대상으로 지정할 수 없으니 (Q)\'실명 다트\'를 맞추기 힘들어요. (W)\'뒤틀린 전진\'이 빠진 것을 확인한 뒤에 (E)\'맹독 다트\'와 평타로 딜교환을 하세요. (E)\'묘목 던지기\'가 깔린 수풀 근처에서는 마오카이의 묘목 폭발을 조심해야 해요.', lv6: '마오카이의 (R)\'대자연의 마수\' 벽이 다가오면 옆으로 이동해 속박을 피하고 길목에 (R)\'유독성 함정\'을 설치하세요. 함정을 밟아 모습이 드러난 마오카이에게 (E)\'맹독 다트\'를 계속 맞춰서 피해를 입히세요. 정글러의 개입에 대비해 버섯을 길목에 배치하며 시야를 확보하세요.', item: '첫 코어로 체력이 많은 마오카이에게 지속 피해를 입히는 리안드리의 고통을 선택하세요. 신발은 마법 저항력과 강인함을 얻을 수 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 체력이 낮은 마오카이를 마무리하며 킬을 노리세요.' },
    '말자하': { lv1: '말자하가 (P)\'공허 태세\'로 피해를 줄이고 있을 때는 (E)\'맹독 다트\'나 평타를 맞춰서 보호 효과를 빨리 없애야 해요. (Q)\'공허의 부름\' 투사체가 날아올 때는 옆으로 움직여서 침묵에 걸리지 않도록 주의하세요. 1~2레벨에는 (Q)\'실명 다트\'로 적을 견제하며 주도권을 가져오세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 지속 피해가 심하니 (W)\'신속한 이동\'을 써서 거리를 벌리세요. (Q)\'실명 다트\'를 말자하 본체에 맞혀 평타를 빗나가게 하고 공허충이 몰려오기 전에 짧게 딜교환을 하세요. (Q)\'공허의 부름\'을 피하면서 평타로 독 피해를 계속 누적시켜 주세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없고 제압 중에는 아무것도 할 수 없으니 주의해야 해요. 말자하가 다가오지 못하게 길목에 (R)\'유독성 함정\'을 미리 깔아 두면 대응하기 편해요. 라인을 밀어 넣을 때는 정글러의 개입에 대비해 항상 시야를 확보하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 피해량을 챙기세요. 신발은 마법 저항력을 높이고 (Q)\'공허의 부름\' 침묵 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 점화로 확실하게 압박하는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트가 (P)\'화강암 방패\'로 피해를 막으며 (Q)\'지진의 파편\'으로 견제하니 (Q)\'실명 다트\'와 평타로 보호막을 빠르게 제거하세요. (Q)\'지진의 파편\'은 대상 지정 스킬이라 미니언 뒤로 숨어도 맞으니 거리를 조절하며 (E)\'맹독 다트\'로 지속 피해를 줘요. 방패가 없는 타이밍에 적극적으로 딜교환을 시도하세요.', lv3: '말파이트가 (W)\'천둥소리\'를 켜고 평타로 다가오면 (Q)\'실명 다트\'를 맞춰 평타 피해를 방지하세요. (E)\'지면 강타\'에 맞으면 공격 속도가 줄어드니 주의하고, (E)\'지면 강타\' 사용 직후에 (W)\'신속한 이동\'을 써서 거리를 벌리며 대응해요. 말파이트의 스킬이 빠진 뒤에 (E)\'맹독 다트\'를 묻힌 평타로 압박하세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없고 맞으면 공중에 뜨니 정글러가 근처에 있을 때 조심하세요. 말파이트가 궁극기를 쓰고 착지하는 경로에 (R)\'유독성 함정\'을 미리 설치해 이동 속도를 늦추세요. 궁극기가 빠진 말파이트를 상대로는 (R)\'유독성 함정\'과 (E)\'맹독 다트\'를 활용해 계속 압박해요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 상대의 체력을 낮춰 압박을 강화하고 킬각을 잡기 쉬워요.' },
    '모데카이저': { lv1: '모데카이저가 (Q)\'말살\'로 미니언과 함께 나를 공격하지 못하게 거리를 유지하세요. (E)\'맹독 다트\'를 꾸준히 맞춰 독을 묻히고 (P)\'암흑 탄생\' 효과가 쌓이기 전에 거리를 벌리며 괴롭혀요. 초반 구간은 사거리를 활용해 견제하며 지나가세요.', lv3: '(E)\'죽음의 손아귀\'는 맞으면 끌려오니 쓰기 전에 사정권 밖으로 움직여 피하세요. 상대가 평타를 치려 할 때 (Q)\'실명 다트\'를 맞히면 피해를 크게 줄일 수 있어요. (W)\'불멸\' 보호막이 켜진 상태라면 무리하게 싸우지 말고 시간을 보내세요.', lv6: '모데카이저가 (R)\'죽음의 세계\'로 끌고 가면 탈출할 수 없으니 (R)\'유독성 함정\'을 미리 깔아두어 접근을 늦추세요. (E)\'죽음의 손아귀\'를 피하며 독 데미지로 압박하고 정글러의 도움을 받는 것이 좋아요. (Q)\'실명 다트\'를 잘 사용해서 상대의 평타를 막으며 버텨보세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해를 극대화하세요. 신발은 마법 저항력과 강인함을 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'불멸\'의 체력 회복 효과를 줄이면 전투를 마무리하기 편해요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던지면 미니언 뒤에 서서 피해를 피하세요. (E)\'맹독 다트\'를 꾸준히 적중시켜 체력을 깎고, 문도가 근접하려 하면 (Q)\'실명 다트\'를 써서 공격을 방해하세요. 문도의 체력 재생이 높아지기 전에 거리 조절을 하며 괴롭히는 것이 중요해요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜고 다가올 때는 (Q)\'실명 다트\'를 사용하여 평타 피해를 막으세요. 문도가 (E)\'둔기에 의한 외상\'을 사용하며 진입할 때 (W)\'신속한 이동\'으로 거리를 벌리며 대응하세요. 문도의 (Q)\'오염된 뼈톱\'이 빗나간 시점에 (E)\'맹독 다트\'를 묻히며 짧게 딜교환을 하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력을 대량으로 회복하니 무리하게 킬을 노리지 마세요. 도주 경로에 (R)\'유독성 함정\'을 미리 깔아두어 문도의 이동을 방해하고 지속 피해를 주세요. 문도가 (P)\'가고 싶은 데로 간다\'로 첫 이동 불가 효과를 무시할 수 있으니 정글러와 함께할 때 스킬을 나눠서 사용하는 게 좋아요.', item: '리안드리의 고통을 첫 코어로 가고 신발은 헤르메스의 발걸음을 선택하세요. 문도 박사의 마법 피해를 줄이면서 적을 불태우는 피해를 주기 위해서예요.', spell: '점멸과 점화를 추천해요. 문도 박사가 (R)\'최대 투여량\'으로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제해야 해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하니 조심하세요. (W)\'신속한 이동\'을 사용해 바루스의 사거리에서 벗어나거나 적절한 거리를 유지하며 성장하세요. 수풀에서 (P)\'유격 전투\'로 투명 상태를 유지하며 바루스가 내 위치를 읽지 못하게 하세요.', lv3: '바루스가 평타를 칠 때마다 (W)\'역병 화살\' 중첩이 쌓이니 (Q)\'실명 다트\'를 맞혀 평타를 빗나가게 하고 중첩이 쌓이지 않게 하세요. 바루스의 (E)\'퍼붓는 화살\'이 깔린 지면은 이동 속도를 늦추니 그 위를 피하며 딜교환하세요. (E)\'맹독 다트\'를 맞힌 뒤 빠르게 거리를 벌려 바루스의 반격으로부터 벗어나세요.', lv6: '바루스의 (R)\'부패의 사슬\'에 맞으면 이동이 막히니 사선으로 움직여 피해야 해요. 라인 곳곳에 (R)\'유독성 함정\'을 설치해 바루스의 움직임을 방해하고 정글러의 개입에 대비하세요. 바루스가 (R)\'부패의 사슬\'을 빗맞히면 (W)\'신속한 이동\'으로 접근해 킬각을 노려보세요.', item: '첫 코어로 리안드리의 고통을 선택해 지속적인 마법 피해를 입히세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 견제를 피하며 빠르게 접근하세요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'의 고정 피해를 위해 세 번의 공격을 노리니 평타 교환을 조심하세요. (Q)\'실명 다트\'를 사용하여 베인의 평타를 억제하며 (E)\'맹독 다트\'로 지속적인 피해를 입히세요. 1~2레벨에는 베인의 (Q)\'구르기\'를 이용한 거리 조절에 맞춰 (W)\'신속한 이동\'으로 적절한 거리를 유지해요.', lv3: '베인이 (Q)\'구르기\'로 접근하며 (E)\'선고\'를 날릴 때 벽 근처에서 밀려나 기절하지 않도록 주의하세요. 베인이 (Q)\'구르기\'를 사용해 거리를 좁히면 (Q)\'실명 다트\'를 맞춰 평타를 못 쓰게 방해해요. (E)\'맹독 다트\'의 중독 효과를 활용하면서 베인이 (W)\'은화살\' 스택을 쌓지 못하도록 거리를 조절하며 딜교환해요.', lv6: '베인이 (R)\'결전의 시간\'을 사용해 (Q)\'구르기\'로 투명해지면 위치를 찾기 어려워지니 조심하세요. 베인이 이동할 예상 경로에 (R)\'유독성 함정\'을 미리 설치하여 둔화를 걸고 모습을 드러내게 만드세요. (Q)\'실명 다트\'를 아껴두었다가 베인이 다시 나타나 공격하려고 할 때 정확히 맞춰서 대응해요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해를 극대화하세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 도망가더라도 점화로 마무리 피해를 높일 수 있어요.' },
    '볼리베어': { lv1: '볼리베어가 (Q)\'번개 강타\'로 빠르게 달려들어 기절시키려 하니 (W)\'신속한 이동\'을 사용해 거리를 유지하세요. (E)\'맹독 다트\'로 계속해서 체력을 깎아내며 상대가 쉽게 다가오지 못하게 해요. 상대의 (Q)\'번개 강타\'가 빠진 타이밍에 짧게 평타를 섞으며 견제하세요.', lv3: '볼리베어가 (Q)\'번개 강타\'로 달려들 때 (Q)\'실명 다트\'를 맞혀 강화 평타를 빗나가게 하세요. (E)\'천공 분열\'의 둔화 범위에 맞으면 빠르게 물러나고, 볼리베어가 보호막을 얻은 상태에서는 딜교환을 피하세요. (E)\'맹독 다트\'의 지속 피해를 입히며 거리 조절에 집중해요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 들어오는 다이브를 조심하고, 도약 지점 주변에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추세요. 볼리베어가 진입한 직후 (Q)\'실명 다트\'로 기본 공격을 빗나가게 하며 정글러가 올 때까지 시간을 벌어요. 라인을 밀어두어도 도약 자체는 막지 못하니 궁극기 낌새가 보이면 포탑 근처로 물러나세요.', item: '리안드리의 고통을 가서 체력이 높은 볼리베어에게 지속적인 마법 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'광란의 상처\'의 체력 회복량을 줄여 킬각을 잡으세요.' },
    '블라디미르': { lv1: '1~2레벨에는 (Q)\'실명 다트\'와 (E)\'맹독 다트\'로 거리를 유지하며 지속적으로 피해를 주세요. 블라디미르의 (Q)\'수혈\' 사거리 밖에서 평타와 (E)\'맹독 다트\'를 섞어주며 체력 차이를 벌리는 것이 좋아요. (Q)\'수혈\'은 대상 지정 스킬이라 걸어서 피할 수 없으니 (W)\'신속한 이동\'으로 사거리 안에 들어가지 않도록 거리를 유지하세요.', lv3: '블라디미르가 (E)\'선혈의 파도\'를 사용할 때는 미니언 뒤에 숨어서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'를 써서 대상으로 지정할 수 없게 되면 스킬을 낭비하지 말고 기다려야 해요. (Q)\'실명 다트\'로 상대의 기본 공격을 방해하며 거리를 조절하세요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용해 감염시키면 받는 피해가 커지니 즉시 거리를 벌리며 후퇴하세요. 이동 경로에 (R)\'유독성 함정\'을 미리 설치하여 블라디미르의 움직임을 둔화시키고 진입을 늦추세요. 상대의 궁극기가 빠진 뒤에 적극적으로 라인을 밀며 압박을 가하는 것이 좋아요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 마법 피해를 입히세요. 신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 블라디미르의 (Q)\'수혈\'을 통한 체력 회복 효과를 감소시켜야 해요.' },
    '뽀삐': { lv1: '(E)\'맹독 다트\'를 이용해 뽀삐가 (P)\'강철의 외교관\'으로 보호막을 얻기 전에 계속 평타 견제를 하세요. 뽀삐가 (Q)\'망치 강타\'로 지대를 만들면 둔화에 걸리지 않게 빠르게 범위를 벗어나야 해요. 벽 근처에 있으면 (E)\'용감한 돌진\'에 밀려 기절할 수 있으니 항상 라인 중앙을 유지하세요.', lv3: '뽀삐가 (E)\'용감한 돌진\'으로 들어올 때 (Q)\'실명 다트\'를 맞춰 평타 피해를 막고 (W)\'신속한 이동\'으로 거리를 벌리세요. 티모에게는 (W)\'굳건한 태세\'에 막힐 돌진기가 없으니 뽀삐가 이 스킬로 이동 속도를 얻어 다가오면 미리 거리를 벌려 두세요. 뽀삐가 방패를 주우러 올 때 (E)\'맹독 다트\'로 짧게 딜교환을 하며 체력을 깎으세요.', lv6: '(R)\'수호자의 심판\' 충전 동작이 보이면 즉시 범위 밖으로 벗어나 멀리 날아가지 않도록 주의하세요. 뽀삐의 진입 경로에 (R)\'유독성 함정\'을 깔아 둔화시키고 (Q)\'실명 다트\'로 대응하며 라인을 압박해 킬각을 잡으세요. 뽀삐가 정글러를 불러 (E)\'용감한 돌진\'으로 벽 기절을 노릴 수 있으니 시야 확보에 신경 쓰세요.', item: '체력이 많은 뽀삐에게 지속 피해를 입히기 위해 리안드리의 고통을 첫 코어로 가세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요. 두 아이템의 조합으로 버티면서 천천히 갉아먹으세요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (E)\'용감한 돌진\'의 벽 기절 위치에서 벗어나고 순간이동으로 빠르게 복귀하여 라인 압박을 유지하세요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나며 뒤의 적까지 맞히니 미니언과 일직선에 서지 마세요. 거리 조절을 하며 (E)\'맹독 다트\'로 계속해서 체력을 깎고 사이온이 다가오지 못하게 하세요. 첫 웨이브부터 꾸준히 견제하며 상대가 쉽게 진입하지 못하는 분위기를 만드세요.', lv3: '사이온이 (Q)\'대량 학살 강타\'를 충전하면 공중에 띄워 기절시키니 충전 동작이 보이면 즉시 옆으로 피하세요. 사이온이 (W)\'영혼의 용광로\' 보호막을 켰을 때는 피해가 흡수되니 보호막이 끝날 때까지 (W)\'신속한 이동\'으로 거리를 벌리세요. 보호막이 사라진 뒤 (Q)\'실명 다트\'를 맞히고 계속 공격해 체력을 깎으세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진해 부딪힌 적을 띄우니, 돌진 경로에서 빠르게 벗어나 충돌을 피하세요. 사이온이 들어올 예상 경로에 (R)\'유독성 함정\'을 미리 설치해 이동 속도를 늦추고 피해를 입히세요. 처치 후에는 (P)\'영광스러운 죽음\'으로 되살아나 빠르게 공격하니 계속해서 거리를 유지하세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 기절과 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온이 라인을 강하게 밀어낼 때 순간이동으로 빠르게 복귀해 경험치 손실을 막으세요.' },
    '사일러스': { lv1: '1~2레벨에는 사일러스가 (Q)\'사슬 후려치기\'로 둔화를 걸며 견제하니 주의하세요. 사일러스가 (P)\'페트리사이트 폭발\'을 사용해 평타를 치려 할 때 (Q)\'실명 다트\'를 맞춰서 공격을 방해하세요. (E)\'맹독 다트\'를 지속적으로 사용하여 사일러스의 체력을 깎으며 거리를 유지해요.', lv3: '사일러스가 (W)\'국왕시해자\'로 돌진해 들어온 뒤 평타를 치려 할 때 (Q)\'실명 다트\'를 맞혀 평타를 빗나가게 하세요. (E)\'도주 / 억압\'의 두 번째 사슬에 맞으면 공중으로 뜨니 사슬이 날아올 때 옆으로 이동해서 피해야 해요. (W)\'신속한 이동\'을 활용해 사일러스와의 적절한 거리를 유지하며 (E)\'맹독 다트\'로 계속 괴롭히세요.', lv6: '사일러스가 (R)\'강탈\'로 티모의 (R)\'유독성 함정\'을 가져가면 사일러스가 버섯을 던져 역습할 수 있으니 조심하세요. 사일러스가 (E)\'도주 / 억압\'으로 들어올 때 (R)\'유독성 함정\'을 미리 깔아두어 이동 속도를 늦추고 거리를 벌리세요. 정글러가 올 때는 (R)\'유독성 함정\'을 길목에 설치하여 사일러스의 진입을 방해하며 대응해요.', item: '첫 코어 아이템으로 리안드리의 고통을 선택하여 지속적인 피해를 입히세요. 신발은 마법 저항력을 높여주고 강인함을 제공하는 헤르메스의 발걸음이 적합해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '세주아니': { lv1: '(E)\'맹독 다트\'로 계속 때리세요. 세주아니가 (W)\'혹한의 서릿발\'로 다가오려고 하면 뒤로 빠지며 거리를 유지하세요. 초반에는 원거리 공격으로 체력을 깎아두는 것이 중요해요.', lv3: '(Q)\'혹한의 맹습\' 돌진에 맞으면 공중으로 뜨니 무빙으로 피하세요. 세주아니가 접근했을 때 (Q)\'실명 다트\'를 사용해 평타 기반의 스턴 중첩을 막으세요. (W)\'신속한 이동\'을 켜고 빠르게 움직여 세주아니의 스킬 사거리 밖으로 벗어나야 해요.', lv6: '(R)\'빙하 감옥\' 올가미가 날아오는 경로를 예측해서 피하세요. 상대가 들어오는 길목에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추고 거리 조절을 하세요. 정글러가 올 때를 대비해 시야를 확보하고 라인을 적절히 밀어두는 것이 좋아요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 강인함으로 기절 지속시간을 줄이고 주문력과 공격 속도를 높여 지속 피해를 입히기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (Q)\'혹한의 맹습\'과 같은 돌진기를 피하고 순간이동으로 빠른 라인 합류를 하기 위해서예요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 빠르게 접근해 강한 평타를 날려요. (E)\'맹독 다트\'로 계속 견제하며 세트가 다가오지 못하게 거리를 유지하세요. 평타를 주고받는 소모전을 하면 (P)\'투기장의 투지\'로 체력을 회복하는 세트가 편하므로 짧게 치고 빠져야 해요.', lv3: '(E)\'안면 강타\'는 양옆에 적이 있어야 기절시키니 미니언과 나 사이에 세트가 오지 않게 위치를 잡으세요. 세트가 투지를 모아 (W)\'강펀치\'를 쓸 때는 중심선에서 벗어나 물리 피해만 입도록 옆으로 피하세요. (Q)\'실명 다트\'를 사용해 세트의 (Q)\'주먹다짐\' 평타 피해를 무효화하며 일방적으로 공격하세요.', lv6: '(R)\'대미 장식\'에 잡혀 내리꽂히면 큰 피해를 입으니 세트의 진입 경로에 (R)\'유독성 함정\'을 깔아 접근을 늦추세요. 세트가 (R)\'대미 장식\'을 쓴 뒤에는 한동안 다시 쓸 수 없으니 (W)\'신속한 이동\'으로 거리를 벌리며 계속 괴롭히세요. 정글러가 올 때 (R)\'유독성 함정\'의 둔화 효과를 활용해 안전하게 빠져나가세요.', item: '내셔의 이빨을 가서 주문력과 공격 속도를 챙겨 지속 피해를 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 체력을 회복하므로 점화의 치유 감소 효과가 유용해요.' },
    '쉔': { lv1: '1~2레벨에는 (E)\'맹독 다트\'로 꾸준히 견제하며 쉔이 다가오지 못하게 하세요. 쉔이 (Q)\'황혼 강습\'을 사용해 기의 검을 가져올 때 옆으로 이동하여 피해를 피하는 것이 중요해요. 쉔이 스킬을 사용해 (P)\'기 보호막\'을 얻었을 때는 무리하게 공격하지 말고 거리를 유지하세요.', lv3: '쉔이 (W)\'의지의 결계\'를 사용하면 기본 공격이 차단되니 결계가 끝난 뒤에 공격을 시작하세요. 쉔의 (E)\'그림자 돌진\'은 도발을 사용하므로 돌진 경로에 서지 않도록 주의하며 (Q)\'실명 다트\'를 활용하세요. 쉔의 (E)\'그림자 돌진\'이 빠진 타이밍에 (E)\'맹독 다트\'를 맞춰서 딜교환을 진행하세요.', lv6: '쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하면 빠르게 라인을 밀어두고 (R)\'유독성 함정\'을 설치하세요. 쉔이 돌아올 때 (R)\'유독성 함정\'을 밟아 둔화가 걸리면 (Q)\'실명 다트\'를 맞춰서 압박하세요. 쉔의 궁극기가 빠진 상태에서 (R)\'유독성 함정\'을 활용해 적극적으로 킬각을 잡으세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 리안드리의 고통은 체력이 많은 쉔에게 지속 피해를 주고 헤르메스의 발걸음은 (E)\'그림자 돌진\' 도발과 (Q)\'황혼 강습\' 둔화의 지속시간을 줄여줘요.', spell: '점멸과 점화를 사용하세요. 쉔의 (P)\'기 보호막\'이 사라진 타이밍에 점화를 걸어 킬을 노리세요.' },
    '쉬바나': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 활용해 쉬바나에게 지속적인 마법 피해를 입히며 거리를 유지하세요. 상대의 (E)\'용암 분출\'이 날아오는 방향을 보고 미리 움직여 둔화와 피해를 피하는 것이 중요해요. (W)\'신속한 이동\'을 켜고 무리하게 쫓지 않으며 체력을 보존하세요.', lv3: '쉬바나가 (Q)\'잉걸불 일격\'을 사용해 접근하면 (Q)\'실명 다트\'를 맞혀 강화 기본 공격 피해를 무효화하세요. (W)\'지옥불 방패\'의 보호막이 사라지고 폭발이 일어날 때까지 거리 조절을 하며 (E)\'맹독 다트\'로 견제하세요. 상대의 (E)\'용암 분출\'을 피해 딜교환 구도를 잡는 것이 핵심이에요.', lv6: '상대가 (R)\'용의 강림\'으로 도약해 들어올 때 예상 경로에 (R)\'유독성 함정\'을 설치해 둔화시키고 피해를 주세요. 용 형상일 때는 (E)\'용암 분출\'의 범위가 넓어지므로 더욱 주의하며 (W)\'신속한 이동\'으로 빠르게 거리를 벌리세요. 라인을 밀어 넣고 정글 진입로에 버섯을 깔아 상대의 추격을 방해하세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 선택하세요. 리안드리의 고통으로 최대 체력이 높은 상대에게 지속 피해를 입히고 헤르메스의 발걸음으로 둔화 지속시간을 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. 용 형상일 때 (W)\'지옥불 방패\' 폭발로 얻는 회복을 점화로 줄이고 마무리 피해도 줄 수 있어요.' },
    '스웨인': { lv1: '스웨인이 (Q)\'죽음의 손길\'로 번개를 쏘며 견제할 때 (W)\'신속한 이동\'을 사용하여 적절히 거리를 조절하세요. (E)\'맹독 다트\'를 적중시켜 지속적인 피해를 입히고 스웨인의 체력을 미리 깎아 두는 것이 중요해요. 스웨인이 (P)\'굶주린 새떼\'로 체력을 회복하며 성장하기 전에 초반부터 강하게 압박하세요.', lv3: '스웨인이 (E)\'속박명령\'을 사용해 파동을 날리면 옆으로 움직여 속박을 피하고 끌어당겨지지 않도록 하세요. 스웨인이 근접해서 딜교환을 시도할 때 (Q)\'실명 다트\'를 맞춰서 평타 공격을 방해해야 해요. (W)\'제국의 눈\'에 맞으면 모습이 드러나니 주의하며 (E)\'맹독 다트\'로 꾸준히 체력을 갉아먹으세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용해 변신하며 들어오면 (R)\'유독성 함정\'을 발밑에 깔아 둔화시키고 빠르게 빠져나가세요. (R)\'악의 승천\'의 체력 흡수는 (Q)\'실명 다트\'로 막을 수 없으니 흡수 범위 밖으로 벗어나는 것이 핵심이에요. 라인을 관리하며 스웨인이 궁극기를 사용하는 타이밍에 (R)\'유독성 함정\'으로 진입 경로를 차단하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 피해를 입히세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인이 (R)\'악의 승천\'이나 (P)\'굶주린 새떼\'로 체력을 회복할 때 점화로 회복 효과를 줄여주세요.' },
    '스카너': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 사용하여 꾸준히 독 피해를 입히며 거리를 유지해요. 스카너가 (Q)\'부서진 대지/지반 돌출\'로 바위를 던지려 할 때 (W)\'신속한 이동\'을 사용하여 위치를 옮기세요. 초반에는 상대의 돌진 거리에 들어가지 않도록 주의하며 평타 견제를 이어가요.', lv3: '스카너가 (E)\'이쉬탈의 격돌\'로 돌진해올 때는 돌진 방향에서 벗어나 벽에 몰리지 않게 하세요. (W)\'대지의 수호자\'를 사용해 보호막을 얻은 상태라면 무리하지 말고 거리를 벌려 스킬을 빼게 만들어요. (E)\'맹독 다트\'를 꾸준히 맞춰 지속적인 마법 피해를 입히는 것이 핵심이에요.', lv6: '스카너가 (R)\'꿰뚫기\'를 사용하여 제압을 시도할 때 매우 조심해야 해요. 이동 경로에 (R)\'유독성 함정\'을 미리 설치하여 상대의 진입을 늦추고 피해를 입히세요. 라인을 관리하며 상대가 함정을 밟도록 유도하고 정글러의 개입에 대비해요.', item: '헤르메스의 발걸음과 리안드리의 고통을 선택해요. 헤르메스의 발걸음으로 스카너의 둔화 지속시간을 줄이고 리안드리의 고통으로 높은 체력을 가진 상대를 압박하기 위해서예요.', spell: '점멸과 정화를 추천해요. 점멸로 (E)\'이쉬탈의 격돌\'을 피하고 정화로 벽 충돌 기절을 풀 수 있지만, (R)\'꿰뚫기\'의 제압은 정화로 풀 수 없어요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 남기며 다가오니 구름 안으로 들어가지 않도록 주의하세요. (Q)\'실명 다트\'를 사용하여 거리를 유지하며 신지드의 체력을 깎아 놓으세요. (W)\'신속한 이동\'을 활용해 신지드가 붙으려 할 때 거리를 벌리는 것이 좋아요.', lv3: '신지드의 (W)\'초강력 접착제\'가 빠진 것을 확인하고 딜교환을 시작하세요. (E)\'던져넘기기\'로 뒤로 넘겨진 뒤 접착제 위에 착지하면 속박에 걸릴 수 있으니 위치를 조심해야 해요. (Q)\'실명 다트\'를 사용하여 신지드의 공격을 방해하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 마시면 능력치가 올라가니 정면 승부는 피하세요. 신지드가 지나갈 경로에 (R)\'유독성 함정\'을 미리 깔아 둔화와 피해를 입히세요. (R)\'유독성 함정\'을 활용해 라인을 관리하며 정글러의 개입에 대비하세요.', item: '리안드리의 고통을 첫 코어로 가고 신발은 헤르메스의 발걸음을 가세요. 마법 저항력과 강인함이 필요하기 때문이에요.', spell: '점멸과 점화를 추천해요. 점화로 신지드의 체력을 깎고 마무리 피해를 입히세요.' },
    '신짜오': { lv1: '1~2레벨에는 (E)\'맹독 다트\'로 지속적으로 견제하며 신 짜오가 다가오지 못하게 거리를 유지하세요. (Q)\'삼조격\'은 강화 평타라 붙으면 걸어서 피할 수 없으니 (Q)\'실명 다트\'로 세 번째 공격을 빗나가게 하거나 미리 거리를 벌리세요.', lv3: '신 짜오가 (W)\'풍전참뢰\'로 둔화를 걸고 (E)\'무쌍돌격\'으로 진입하는 순간 (Q)\'실명 다트\'를 사용해 평타 피해를 막으세요. (Q)\'삼조격\'의 세 번째 공격에 맞지 않도록 주의하며 (W)\'신속한 이동\'으로 거리를 벌려야 해요.', lv6: '신 짜오가 (R)\'현월수호\'를 사용하면 원거리 공격이 통하지 않으니 효과가 끝날 때까지 기다리세요. 상대의 진입 경로에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추고 추격을 방해해야 해요. 정글 개입이 심한 챔피언이니 라인을 너무 밀지 말고 주의하세요.', item: '판금 장화와 내셔의 이빨을 선택하세요. 판금 장화는 기본 공격으로 받는 피해를 줄여주며 내셔의 이빨은 공격 속도와 주문력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점멸로 진입을 피하고 점화로 (P)\'결심\'의 체력 회복 효과를 줄이며 마무리하세요.' },
    '아이번': { lv1: '(E)\'맹독 다트\'를 사용하여 아이번의 체력을 깎으며 거리를 조절하세요. 아이번이 (Q)\'덩굴뿌리\'를 사용하여 속박을 시도할 때 (W)\'신속한 이동\'을 활용해 피해를 최소화하며 웨이브를 관리해요. 초반에는 무리하게 진입하기보다 견제 위주로 플레이하세요.', lv3: '아이번이 (E)\'보호의 씨앗\'으로 보호막을 생성하면 무리한 딜교환을 피하세요. 아이번에게 (Q)\'실명 다트\'를 적중시켜 공격을 방해하며 (E)\'맹독 다트\'를 통한 지속적인 피해를 입히는 것이 중요해요. 상대의 (Q)\'덩굴뿌리\'를 피하며 거리를 유지하세요.', lv6: '아이번이 (R)\'데이지!\'를 소환하면 (R)\'유독성 함정\'을 길목에 설치하여 진입을 방해하세요. (R)\'데이지!\'가 연속 공격으로 공중으로 띄우는 효과를 내지 못하도록 조심하며 싸워야 해요. 정글러의 개입에 대비해 버섯을 미리 깔아두며 라인을 관리하세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 구매해요. 마법 저항력과 강인함으로 상대의 군중 제어 지속시간을 줄이고 리안드리의 고통으로 적을 불태워요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'덩굴뿌리\'를 피하고 점화로 마무리 피해를 입혀요.' },
    '아지르': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 사용하여 지속적으로 피해를 입히세요. 아지르가 (Q)\'사막의 맹습\'을 사용해 둔화를 걸려고 하면 좌우로 움직여 피해 주세요. 무리하게 다가가기보다 거리 조절을 하며 체력을 갉아먹으세요.', lv3: '(Q)\'실명 다트\'를 아지르 본체에 맞혀 평타를 빗나가게 하세요. 상대가 (E)\'신기루\'로 빠르게 진입하려고 하면 (W)\'신속한 이동\'을 켜서 거리를 벌리며 대응하세요. 병사가 없는 틈을 타 짧게 공격하고 빠지는 식으로 딜교환을 해요.', lv6: '(R)\'유독성 함정\'을 아지르의 예상 이동 경로에 설치해 이동 속도를 늦추고 피해를 주세요. (R)\'황제의 진영\'에 밀려나면 위험하므로 거리 조절에 유의하며 킬각을 잡으세요. 정글러가 올 때 버섯을 깔아 추격 경로를 둔화시켜 도움을 받으세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 헤르메스의 발걸음으로 마법 저항력을 높여 생존하고 내셔의 이빨로 공격 속도와 주문력을 얻어 피해량을 높이세요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (R)\'황제의 진영\' 같은 위협적인 스킬을 피하고 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸며 압박하니 (E)\'맹독 다트\'를 활용해 거리를 유지하며 견제하세요. 아칼리가 (P)\'암살자의 표식\' 원 경계를 넘으며 강화 평타를 치지 못하게 적절한 거리를 유지하는 것이 중요해요.', lv3: '아칼리가 (E)\'표창곡예\'로 돌진해 올 때 (Q)\'실명 다트\'를 맞혀 강화 평타를 빗나가게 하세요. (W)\'황혼의 장막\' 안에서는 (Q)\'실명 다트\'가 닿지 않으니 연막이 걷힌 뒤에 스킬을 사용하는 것이 좋아요.', lv6: '아칼리가 (R)\'무결처형\'으로 진입할 때 이동 경로에 (R)\'유독성 함정\'을 설치해 둔화를 걸고 위치를 드러내세요. (W)\'황혼의 장막\'을 사용한 아칼리는 (Q)\'실명 다트\' 같은 대상 지정 스킬을 피할 수 있으니 주의하며 싸우세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 피해를 입히세요. 신발은 아칼리의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎아 마무리하는 데 도움을 주세요.' },
    '아크샨': { lv1: '1~2레벨에는 (E)\'맹독 다트\'로 꾸준히 견제하며 거리를 조절하세요. 아크샨의 (Q)\'복수의 부메랑\'이 챔피언에게 맞으면 이동 속도가 빨라지니 주의해야 해요. 미니언을 받아먹으며 안전한 위치를 유지하세요.', lv3: '3레벨 이후 아크샨이 (E)\'영웅의 비상\'으로 진입할 때는 이미 시작된 기동을 막을 수 없으니 갈고리가 걸리기 전에 거리를 벌리세요. 아크샨이 (P)\'비열한 싸움\' 보호막을 얻지 못하도록 짧게 교전하고 빠르게 빠져나오세요. (W)\'신속한 이동\'을 사용하여 아크샨의 움직임에 대응하세요.', lv6: '6레벨 이후 아크샨의 (R)\'인과응보\'는 체력이 낮은 적에게 치명적이니 항상 체력을 관리하세요. 아크샨이 이동하는 경로에 (R)\'유독성 함정\'을 설치하여 접근을 방해하세요. 라인을 조절하며 정글러의 개입을 유도하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주며 리안드리의 고통은 스킬 공격으로 적을 불태워 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 아크샨의 돌진에 대응하고 점화로 교전의 강도를 높이세요.' },
    '아트록스': { lv1: '(Q)\'다르킨의 검\' 끝자락에 맞으면 공중으로 띄워지니 범위를 피해 거리 조절을 하세요. (E)\'맹독 다트\'를 활용해 평타로 지속 피해를 입히며 체력을 깎아내세요. (P)\'사신 태세\'가 적용된 평타는 회복을 동반하므로 무리하게 평타 교환을 하지 마세요.', lv3: '(W)\'지옥사슬\'에 맞으면 일정 시간 안에 범위를 벗어나야 끌려가지 않으니 표시가 보이면 즉시 이동하세요. 아트록스가 (E)\'파멸의 돌진\'으로 진입하며 (Q)\'다르킨의 검\'을 사용할 때 (W)\'신속한 이동\'으로 거리를 벌리세요. 상대의 평타 회복을 막기 위해 (Q)\'실명 다트\'를 맞히고 짧게 딜교환을 하세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 공격력과 회복량이 늘어나니 정면 교환을 피하고 뒤로 물러나세요. 진입 경로에 (R)\'유독성 함정\'을 미리 설치해 이동 속도를 늦추고 접근을 방해하세요. 라인을 당겨 정글러의 개입을 유도하며 (W)\'신속한 이동\'으로 안전하게 퇴각하세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'의 회복량을 낮춰 마무리하기 편해요.' },
    '암베사': { lv1: '암베사가 (P)\'용사냥개의 발걸음\'으로 돌진하며 다음 평타를 강화하기 전에 (E)\'맹독 다트\'와 (Q)\'실명 다트\'로 거리를 두며 견제하세요. 암베사가 (Q)\'교활한 휩쓸기\'를 사용하여 빠르게 다가오지 못하도록 미니언 사이에서 거리를 조절하며 대응하세요.', lv3: '암베사가 (E)\'찢어 가르기\'로 둔화를 걸고 돌진해올 때 (Q)\'실명 다트\'를 사용하여 강화된 평타를 맞지 않도록 주의하세요. (W)\'배척\'을 준비할 때 피해를 입히지 않도록 주의하며 잠시 물러나 있는 것이 좋아요. 암베사가 스킬을 사용한 직후에는 (W)\'신속한 이동\'을 활용해 거리를 벌리며 싸우세요.', lv6: '암베사의 (R)\'공개 처형\'은 저지 불가 상태로 순간 이동해 제압하니 버섯으로 막을 수 없고, 대신 주변에 (R)\'유독성 함정\'을 깔아 두어 궁극기 이후 추격을 늦추세요. 제압 중에는 스킬을 사용할 수 없으므로 암베사의 궁극기가 보이면 위치 선정을 신중히 해야 해요. 암베사가 (R)\'공개 처형\' 이후 체력을 회복하며 버티려 할 때 정글러와 함께 압박하세요.', item: '리안드리의 고통을 첫 코어로 가고 판금 장화를 신으세요. 리안드리의 고통은 지속 피해를 입히기에 좋고 판금 장화는 암베사의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 암베사가 (R)\'공개 처형\'으로 스킬 피해를 입혀 체력을 회복하는 것을 막기 위해 점화가 필요해요.' },
    '애니비아': { lv1: '애니비아가 (Q)\'냉기 폭발\'을 날리면 구체가 터지는 지점을 피해 옆으로 움직이세요. (W)\'신속한 이동\'을 사용하여 애니비아의 사거리 안으로 들어가는 타이밍을 조절하며 대응해야 해요. (E)\'맹독 다트\'를 활용해 애니비아의 체력을 깎으며 압박을 시도하세요.', lv3: '애니비아가 (Q)\'냉기 폭발\'로 냉각을 시킨 뒤 (E)\'동상\'을 사용하면 피해가 매우 강력해지니 구체를 피하는 것이 중요해요. (W)\'결정화\' 벽에 갇히지 않도록 위치를 잡으며 애니비아의 (Q)\'냉기 폭발\'이 빠진 순간에 (Q)\'실명 다트\'를 맞히세요. (W)\'신속한 이동\'을 섞어 사용하며 딜교환을 하세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 소환해 둔화를 걸면 길목에 (R)\'유독성 함정\'을 설치하여 움직임을 제약하세요. 애니비아가 치명적인 피해를 입고 (P)\'환생\'한다면 알을 즉시 공격해 다시 일어서지 못하게 해야 해요. 정글러가 근처에 있을 때 (R)\'유독성 함정\'을 깔아두면 애니비아를 압박하기 쉬워요.', item: '첫 코어 아이템으로 리안드리의 고통을 선택해 (E)\'맹독 다트\'와 함께 지속적인 피해를 주세요. 신발은 애니비아의 마법 피해와 (Q)\'냉기 폭발\' 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 고정 피해를 통해 체력이 낮은 애니비아를 빠르게 처치하여 (P)\'환생\'을 방지하세요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 견제하며 두 번째 중첩으로 띄워 올릴 수 있으니, 회오리가 준비된 상태에서는 거리를 넉넉히 벌리세요. (P)\'낭인의 길\' 보호막이 켜져 있을 때 평타를 치면 피해가 줄어드니, 기본 공격으로 보호막을 먼저 걷어낸 뒤 (E)\'맹독 다트\'의 지속 피해를 입히세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 들어올 때 당황하지 말고 뒤로 물러나며 거리를 유지하세요.', lv3: '야스오가 (W)\'바람 장막\'을 설치하면 (Q)\'실명 다트\'가 막히니, 벽이 사라진 후에 스킬을 사용해 시야를 가리세요. (E)\'질풍검\'으로 빠르게 접근하는 야스오에게 (Q)\'실명 다트\'를 맞혀 기본 공격을 빗나가게 하되, (Q)\'강철 폭풍\'은 스킬이라 실명으로 막을 수 없으니 회오리 방향에서 벗어나세요. (W)\'신속한 이동\'을 켜서 야스오의 회오리바람 사거리 밖으로 빠르게 벗어나며 짧은 딜교환을 유도하세요.', lv6: '야스오는 적이 공중에 떠야 (R)\'최후의 숨결\'을 쓸 수 있으니, (Q)\'강철 폭풍\'의 회오리에 맞지 않도록 각별히 주의하세요. 야스오가 (E)\'질풍검\'으로 진입할 것으로 예상되는 경로와 미니언 사이에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추고 피해를 입히세요. 정글러가 띄우기 스킬을 가졌다면 야스오의 궁극기 연계가 가능하니 라인을 너무 밀지 말고 아군 포탑 근처에서 대기하세요.', item: '리안드리의 고통을 첫 코어로 가서 (E)\'맹독 다트\'와 함께 지속적인 마법 피해를 입히세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'실명 다트\'로 야스오의 공격을 막은 뒤 점화로 마무리 피해를 더해 킬각을 잡으세요.' },
    '오공': { lv1: '오공이 (Q)\'파쇄격\'을 사용해 사거리가 늘어난 평타로 접근할 때 (Q)\'실명 다트\'를 맞혀 강화 평타를 빗나가게 하세요. (E)\'맹독 다트\'의 지속 피해를 입히며 오공의 (P)\'바위 피부\'가 쌓이기 전에 최대한 멀리서 견제해야 해요. 오공의 돌진 전에 미리 거리를 벌리는 것이 중요해요.', lv3: '오공이 (E)\'근두운 급습\'으로 돌진해 올 때 (Q)\'실명 다트\'를 맞춰서 오공을 실명시키며 대응하세요. (W)\'분신 전사\'가 생성되면 분신이 아닌 진짜 오공을 찾아 스킬을 맞히는 것이 중요해요. 오공이 (W)\'분신 전사\'를 사용해 투명해진 순간에는 무리하게 싸우지 말고 거리를 두세요.', lv6: '오공이 (R)\'회전격\'으로 공중에 띄우면 스킬을 쓸 수 없으니 정면에서 맞서지 말고 주의하세요. 오공이 다가오는 길목에 (R)\'유독성 함정\'을 미리 설치해 이동 속도를 늦추고 위치를 드러내게 만드세요. 오공의 궁극기가 빠진 뒤에 (R)\'유독성 함정\'과 함께 공격적으로 딜교환을 시도하세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 마법 피해를 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 오공에게 추가 피해를 입히며 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 던진 뒤 다시 불러들여 경로상의 적에게 피해를 주니 옆으로 계속 움직여서 피하세요. (E)\'맹독 다트\'로 짤짤이 견제를 넣으며 오로라가 다가오지 못하게 거리 조절을 하세요. 오로라는 피해를 입힐 때 (P)\'영혼 방호술\'로 체력을 회복하니 일방적으로 맞는 교환을 피하며 평타로 체력 차이를 벌리세요.', lv3: '(E)\'마법의 문\'을 사용해 둔화를 걸고 뒤로 물러나는 오로라를 무리하게 쫓지 말고 (W)\'신속한 이동\'으로 거리만 유지하세요. 오로라가 (W)\'장막 너머로\'를 사용해 투명 상태가 되어 접근할 때 (Q)\'실명 다트\'를 미리 준비해서 평타 딜교환을 차단하세요. (Q)\'이중 저주\'의 두 번째 타격 경로에서 벗어난 뒤 (E)\'맹독 다트\' 평타를 섞어 짧은 딜교환을 반복하세요.', lv6: '(R)\'세계의 경계\' 영역 안에 갇히면 둔화 때문에 도망치기 힘드니 영역 가장자리에 (R)\'유독성 함정\'을 설치해 도주 경로를 방해하세요. 오로라가 영역 내에서 순간이동하며 공격할 때 (Q)\'실명 다트\'를 적중시켜 딜로스를 유도하고 빠르게 영역 밖으로 나가세요. 정글러가 올 때는 (W)\'장막 너머로\'로 도망칠 수 있으니 미리 체력을 깎아두는 게 좋아요.', item: '내셔의 이빨을 첫 코어로 가서 (E)\'맹독 다트\'의 공격 속도와 주문력을 높여 압박하세요. 신발은 오로라의 마법 피해를 줄이고 (E)\'마법의 문\' 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하며 버티는 것을 점화의 치유 감소 효과로 억제해야 해요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\'으로 방어력과 마법 저항력이 높아서 초반에 체력을 깎기 힘들어요. (Q)\'용암 균열\'은 지면에 둔화를 주고 기둥을 세우니 표시를 보고 옆으로 피하세요. (E)\'맹독 다트\'를 계속 맞히며 체력을 조금씩 깎아내세요.', lv3: '(E)\'화염 돌진\'은 지형지물에 부딪히면 공중으로 띄우니 벽 근처에 서지 마세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되어 이동 불가 지속시간이 늘어나니 주의하세요. 오른이 기본 공격으로 밀어내려 할 때 (Q)\'실명 다트\'를 써서 공격을 빗나가게 하세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령이 다가올 때 오른이 따라 들어올 길목에 (R)\'유독성 함정\'을 깔아 오른의 이동 속도를 늦추세요. 정령에 맞으면 둔화되고 불안정 상태가 되며, 오른이 재사용해 박치기로 방향을 바꾼 정령에 맞으면 공중으로 뜨니 정령의 경로에서 벗어나세요. 오른은 (P)\'간이 대장간\'으로 아이템을 빠르게 맞추니 무리하게 킬각을 잡기보다 정글러를 부르세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 적에게 지속 피해를 주세요. 신발은 강인함으로 둔화 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 체력이 많고 단단해서 빠르게 처치하기 어려우니 순간이동으로 라인 복귀에 집중하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 둔화를 걸고 접근하려 할 때 (E)\'맹독 다트\'로 계속 견제하세요. 도끼를 주우러 오는 경로를 피해 거리를 유지하며 평타를 섞어주는 것이 중요해요. 1~2레벨에는 올라프의 근접 공격력이 강하니 무리하게 딜교환 하지 마세요.', lv3: '올라프가 (W)\'버티기\'를 켜고 달려들면 (Q)\'실명 다트\'를 사용해 기본 공격을 빗나가게 하세요. (W)\'신속한 이동\'을 켜서 (Q)\'역류\'의 둔화와 접근을 피하며 거리 조절을 하는 것이 핵심이에요. (E)\'무모한 강타\'는 실명으로 막을 수 없는 고정 피해 스킬이므로 거리가 좁혀졌을 때 빠르게 빠지세요.', lv6: '(R)\'라그나로크\'를 사용한 올라프는 이동 불가 및 방해 효과에 면역이 되니 무리하게 막아서지 마세요. 궁극기가 켜진 동안에는 (W)\'신속한 이동\'으로 최대한 도망치며 지속 시간이 끝나기를 기다려야 해요. 체력이 낮아질수록 (P)\'광전사의 분노\'로 생명력 흡수가 늘어나니 마무리까지 방심하지 마세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 올라프의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'광전사의 분노\'의 생명력 흡수를 억제하기 위해 점화의 치유 감소 효과가 필요해요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\' 중첩을 쌓아 돌진하며 공중으로 띄우려 하니 거리를 계속 유지하세요. (E)\'맹독 다트\'를 활용해 요네가 다가오기 전에 지속적인 마법 피해를 입히며 견제해요. 요네가 기본 공격을 하기 전에 뒤로 물러나 피해를 줄이세요.', lv3: '요네가 (E)\'영혼해방\'을 써서 빠르게 진입하면 (Q)\'실명 다트\'를 맞춰서 기본 공격을 못 하게 방해하세요. 요네가 (W)\'영혼 가르기\'로 보호막을 얻으며 들어올 때는 무리하게 맞서지 말고 거리를 벌려야 해요. 요네의 (Q)\'필멸의 검\' 중첩이 쌓이지 않았을 때 짧게 딜교환을 하고 빠지세요.', lv6: '요네가 (R)\'운명봉인\'을 사용해 경로상의 적을 끌어당기며 공중으로 띄우니 이동 경로에 주의하세요. 요네가 돌아오는 위치나 도망가는 길목에 (R)\'유독성 함정\'을 미리 설치해 둔화 효과를 노려요. 요네의 궁극기를 맞은 후에는 정글러의 개입이 쉬우니 라인을 너무 밀지 마세요.', item: '판금 장화를 선택해 요네의 기본 공격 피해를 줄이세요. 리안드리의 고통을 첫 코어로 가서 (E)\'맹독 다트\'의 피해를 극대화해요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\' 보호막을 사용한 직후에 점화를 사용해 체력을 깎으세요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 처치하며 무덤을 쌓지 못하도록 (E)\'맹독 다트\'를 활용해 미니언과 요릭을 함께 견제하세요. 수풀 속에서 (P)\'유격 전투\'를 이용해 투명 상태를 유지하며 적절한 거리를 유지한 채 꾸준히 피해를 입히는 것이 좋아요. 요릭의 공격이 닿기 전에 거리를 조절하며 체력을 미리 깎아두세요.', lv3: '요릭이 (E)\'애도의 안개\'를 던져 표식을 남기면 안개 망령이 쫓아오니 조심해야 해요. 요릭이 (Q)\'최후의 의식\'을 사용해 강화 공격을 하려 할 때 (Q)\'실명 다트\'를 맞춰서 피해를 줄이세요. (W)\'망자의 진\' 벽에 갇히면 빠르게 평타를 쳐서 부수거나 반대 방향으로 이동하세요.', lv6: '요릭이 (R)\'군도의 장송곡\'을 사용하여 안개 마녀를 소환하면 안개 마녀와 소환물이 한꺼번에 몰려오니 주의하세요. 요릭의 이동 경로에 (R)\'유독성 함정\'을 설치해 진입을 늦추고 지속적인 피해를 입히세요. 마녀가 나타나면 무리하게 싸우지 말고 (R)\'유독성 함정\'의 둔화 효과를 이용해 거리를 벌리며 싸워야 해요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 입히세요. 신발은 요릭의 기본 공격 피해를 줄이기 위해 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 체력을 회복하는 것을 점화로 억제하며 압박할 수 있어요.' },
    '우디르': { lv1: '우디르는 (E)\'불길 쇄도\'로 빠르게 접근해 기절을 노리니 평타 사거리를 주지 마세요. (E)\'맹독 다트\'로 지속적인 피해를 주며 체력을 깎아두는 것이 좋아요. 우디르가 달려들면 (W)\'신속한 이동\'을 켜서 거리를 유지하세요.', lv3: '(Q)\'야생 발톱\'을 켠 우디르가 평타를 치려 하면 (Q)\'실명 다트\'로 공격을 무효화하세요. (W)\'강철 갑옷\'의 보호막과 회복 평타가 시작될 때는 딜교환을 피하고 효과가 끝날 때까지 기다리세요. (E)\'불길 쇄도\'의 기절이 빠진 것을 확인한 뒤에 공격적으로 딜을 넣으세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'으로 둔화를 걸며 다가오면 (R)\'유독성 함정\'을 깔아 이동 속도를 더 늦추세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되면 억지로 멈추려 하지 말고 거리만 벌리세요. 함정을 정글 진입로에 설치해 갱킹을 대비하며 라인을 관리하세요.', item: '리안드리의 고통과 판금 장화를 가세요. 체력이 높은 우디르에게 지속 피해를 주고 (Q)\'야생 발톱\'의 물리 피해를 줄여야 해요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 회복하는 양을 줄여 마무리하기 좋아요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'을 던져 둔화를 걸고 다가오니, 투사체가 떨어지는 위치를 피해 거리를 유지하세요. (E)\'맹독 다트\' 평타로 지속적인 피해를 입히며 상대를 압박하고, (W)\'신속한 이동\'을 켜서 접근 타이밍을 조절해요. 첫 웨이브부터 짧은 견제를 반복하며 우르곳의 체력을 깎아두세요.', lv3: '우르곳이 (E)\'경멸\'로 돌진해 나를 뒤로 던지려 하면 옆으로 비켜서서 피하고, 돌진이 빗나간 직후에 (Q)\'실명 다트\'를 사용해 평타 피해를 무효화하세요. (W)\'심판의 원\'이 켜졌을 때는 무리하게 딜교환하지 말고 (W)\'신속한 이동\'으로 빠르게 거리를 벌려 사격 범위에서 벗어나야 해요. (Q)\'부식성 폭약\'을 피해 표식이 남지 않았다면 우르곳보다 미니언이 가까운 위치에서 짧게 견제하세요.', lv6: '우르곳의 (R)\'불사의 공포\' 섬광탄에 맞고 체력이 낮아지면 제압당해 처형될 수 있으니, 체력이 낮은 상태에서 우르곳 곁에 머물지 마세요. 우르곳이 (E)\'경멸\'로 진입하려는 경로에 (R)\'유독성 함정\'을 미리 깔아두어 접근 속도를 늦추고 둔화시켜 진입을 방해해요. 정글러의 개입이 예상되는 강가 쪽에는 (R)\'유독성 함정\'을 배치해 적의 위치를 파악하고 도주 경로를 확보하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 우르곳에게 지속적인 마법 피해를 입히세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳이 (R)\'불사의 공포\'로 처형하기 전에 점화의 추가 피해로 빠르게 체력을 깎아 처치하세요.' },
    '워윅': { lv1: '워윅이 (Q)\'야수의 송곳니\'로 도약하기 전에 사거리 밖에서 거리를 조절하세요. 1~2레벨에는 (E)\'맹독 다트\'로 지속적인 피해를 입히며 워윅의 체력을 깎아두는 것이 중요해요. 워윅의 체력이 절반 아래로 내려가면 (P)\'끝없는 허기\'로 회복량이 늘어나니 무리한 접근은 자제하세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용해 피해를 줄이고 공포를 걸려 하면 (W)\'신속한 이동\'으로 거리를 벌리세요. (Q)\'야수의 송곳니\'는 맞으면 회복을 막을 수 없으니 도약 전에 거리를 벌리고, 평타 교환 때 (Q)\'실명 다트\'로 평타를 빗나가게 하세요. 워윅의 체력이 낮아져 (W)\'피의 사냥\' 효과가 활성화되면 이동 속도가 매우 빨라지니 주의해야 해요.', lv6: '워윅의 (R)\'무한의 구속\'은 제압을 걸며 제압 중에는 스킬을 쓸 수 없으니 정글러의 위치를 항상 확인하세요. 워윅이 도약할 경로에 (R)\'유독성 함정\'을 미리 설치해 이동 속도를 늦추고 모습을 드러내게 만드세요. 제압은 정화로 풀 수 없으므로 체력이 낮을 때는 라인을 당겨서 위험을 피하세요.', item: '리안드리의 고통을 첫 코어로 올려서 (E)\'맹독 다트\'와 함께 지속적인 피해를 입히세요. 신발은 워윅의 공포 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 회복력을 억제하세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 진입하며 체력을 회복해요. (E)\'맹독 다트\'로 꾸준히 견제하되, 상대가 진입하는 순간 (Q)\'실명 다트\'를 맞춰 평타 피해를 막아내세요. (W)\'신속한 이동\'을 켜고 상대의 (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 거리를 벌리세요.', lv3: '(E)\'쌍검협무\'의 두 번째 검이 날아오는 길목을 피해 기절과 표식을 허용하지 마세요. 표식이 남으면 (Q)\'칼날 쇄도\' 재사용 대기시간이 초기화되어 계속 추격당해요. (W)\'저항의 춤\' 충전 중에는 피해가 감소하니 충전이 끝난 뒤에 (Q)\'실명 다트\'를 사용해 공격을 무력화하세요.', lv6: '(R)\'선봉진격검\'에 맞으면 표식이 생기고 결계 안에서 둔화되니 결계 밖으로 빠르게 벗어나세요. 이렐리아가 진입할 예상 경로에 (R)\'유독성 함정\'을 설치해 접근을 늦추고 피해를 입히세요. 정글러가 올 때 (R)\'유독성 함정\'을 내 뒤에 깔아두면 추격하는 적을 둔화시키기 편해요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 줄여 킬각을 잡으세요.' },
    '일라오이': { lv1: '1~2레벨에는 (P)\'고대신의 예언자\'로 소환된 촉수 근처를 피하며 (E)\'맹독 다트\'로 일라오이를 견제하세요. 일라오이가 (Q)\'촉수 강타\'를 사용하려고 하면 촉수의 움직임을 보고 빠르게 거리를 벌려야 해요. 촉수가 없는 곳에서 지속적인 피해를 입히며 버티세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 일라오이가 분리된 영혼을 때릴 때 피해 일부가 나에게 들어오니 영혼 곁에서 싸우지 마세요. 영혼에서 너무 멀어지면 내가 숙주가 되어 촉수가 나를 노리니 촉수를 소환할 벽에서 떨어진 쪽으로 물러나세요. 일라오이가 (W)\'혹독한 가르침\'으로 돌진해 공격할 때 (Q)\'실명 다트\'를 맞히면 기본 공격을 빗나가게 할 수 있어요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하여 많은 촉수를 소환하면 즉시 범위를 벗어나세요. 일라오이가 다가오는 길목에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추며 거리를 유지하세요. 일라오이가 궁극기를 쓴 뒤에는 촉수가 사라질 때까지 근처에서 싸우지 말고 라인을 당겨 받으세요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 피해를 입히세요. 신발은 일라오이의 물리 피해를 줄이기 위해 판금 장화를 추천해요.', spell: '점멸과 탈진을 추천해요. 일라오이가 (W)\'혹독한 가르침\'으로 들어올 때 탈진을 사용해 피해량을 감소시키세요.' },
    '자크': { lv1: '(E)\'맹독 다트\'로 계속해서 체력을 깎으며 거리를 유지하세요. 자크의 (Q)\'탄성 주먹\'은 사거리가 길고 첫 적을 붙잡으니 미니언 뒤에 서서 맞지 않게 조심하세요. 자크가 (P)\'세포 분열\' 조각을 흡수해 회복하지 못하도록 조각 주변에 계속 압박을 가하세요.', lv3: '자크가 (E)\'새총 발사\'를 쓰기 위해 뒤로 몸을 당기는 모습이 보이면 즉시 옆으로 피하세요. (W)\'불안정 물질\'의 폭발 범위에 닿지 않게 주의하며 (Q)\'실명 다트\'를 맞혀 기본 공격 딜교환을 차단하세요. (W)\'신속한 이동\'을 켜서 거리를 조절하며 (E)\'맹독 다트\'로 괴롭히세요.', lv6: '자크가 (R)\'바운스!\'로 튀어 올라올 때 이동 경로에 (R)\'유독성 함정\'을 깔아 둔화시키고 접근을 늦추세요. 자크가 치명상을 입어 (P)\'세포 분열\'로 갈라졌을 때 조각들을 빠르게 공격해 부활을 막으세요. 정글러가 올 때 버섯을 입구에 설치해 진입로를 제한하며 안전하게 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 자크에게 지속적인 마법 피해를 입히세요. 신발은 (W)\'불안정 물질\' 같은 마법 피해를 줄이고 강인함을 얻는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 자크가 (P)\'세포 분열\' 조각을 흡수해 회복하는 양을 줄이세요.' },
    '자헨': { lv1: '1~2레벨에는 자헨이 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 거리를 유지하세요. (Q)\'실명 다트\'를 사용하여 자헨의 기본 공격을 방해하고 (E)\'맹독 다트\'로 지속적인 피해를 입히며 견제하세요. 자헨이 붙으려고 하면 (W)\'신속한 이동\'을 사용해 거리를 벌리는 것이 좋아요.', lv3: '자헨이 (W)\'공포의 귀환\'을 사용하여 끌어당기려 하면 옆으로 움직여 피하세요. 자헨이 (E)\'찬란한 쇄도\'로 돌진해 들어올 때 (Q)\'실명 다트\'를 맞히면 자헨의 후속 공격을 막을 수 있어요. 자헨의 (Q)\'다르킨의 글레이브\' 재사용 효과인 공중 띄우기가 빠졌을 때 짧게 딜교환을 하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 공중으로 날아오르면 착지 지점을 예측해 (R)\'유독성 함정\'을 미리 설치하세요. 자헨이 궁극기로 체력을 회복하며 압박할 때 함정의 둔화 효과로 거리 조절을 하세요. 자헨의 (P)\'전쟁 단련\' 중첩이 가득 차서 부활할 수 있으니 적의 체력이 낮을 때 확실히 몰아붙여야 해요.', item: '첫 코어로 리안드리의 고통을 선택해 지속 피해를 높이세요. 신발은 자헨의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화의 치유 감소 효과가 필요해요.' },
    '잭스': { lv1: '(E)\'맹독 다트\'를 계속 사용해 잭스의 체력을 깎으며 거리를 유지하세요. 잭스가 (Q)\'도약 공격\'으로 빠르게 접근하려고 하면 뒤로 물러나며 평타 견제를 이어가세요. (P)\'가차없는 맹공\'으로 공격 속도가 오르기 전에 짧게 공격하고 빠지세요.', lv3: '잭스가 (E)\'반격\'을 켜면 모든 기본 공격을 회피하니 즉시 멈추고 거리를 벌리세요. (E)\'반격\'의 기절 효과가 끝나면 (Q)\'실명 다트\'를 사용해 잭스가 평타를 치지 못하게 방해하고 (E)\'맹독 다트\' 피해를 누적하세요. (W)\'무기 강화\'의 강력한 한 방을 맞지 않도록 (W)\'신속한 이동\'으로 빠르게 움직이며 거리 조절을 하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하면 방어력과 마법 저항력이 올라가니 무리한 정면 승부는 피하세요. 잭스가 들어오는 경로에 (R)\'유독성 함정\'을 미리 설치해 둔화시키고 접근을 어렵게 만드세요. 정글러가 올 때 버섯으로 잭스의 위치를 드러내고 속도를 늦춰서 빠르게 처치하세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 부족한 피해량을 보충하고 잭스를 확실하게 처치하기 위해서예요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 멀리서 쏘며 압박할 때 궤적 밖으로 거리를 유지하세요. 제이스가 미니언을 먹으러 가까이 오면 (E)\'맹독 다트\'를 묻히며 딜교환을 시도해요. (W)\'신속한 이동\'을 사용하여 제이스의 사거리에서 빠르게 벗어나세요.', lv3: '제이스가 해머 형태로 (E)\'천둥 강타\'를 사용해 뒤로 밀어내면 바로 거리를 벌리세요. 제이스가 (W)\'초전하\'를 켜고 달려들 때는 (Q)\'실명 다트\'를 맞혀 평타 피해를 무력화해야 해요. (E)\'가속 관문\'을 통과한 (Q)\'전격 폭발\'의 넓은 범위에 맞지 않도록 주의하며 대응하세요.', lv6: '제이스가 (R)\'머큐리 캐논\'을 사용해 방어력을 낮추면 교전이 위험하니 거리를 벌리세요. 제이스가 이동하는 길목에 (R)\'유독성 함정\'을 미리 설치하여 이동 속도를 늦추고 위치를 노출시키세요. 해머로 변환한 제이스가 (E)\'천둥 강타\'를 쓰고 들어오면 (R)\'유독성 함정\' 위로 유도하여 정글러를 부르세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'실명 다트\'로 제이스의 평타를 막은 뒤 점화를 사용해 킬각을 잡으세요.' },
    '초가스': { lv1: '초가스가 (Q)\'파열\'로 지면을 파열시켜 공중으로 띄우려 할 때 바닥의 표시를 보고 범위 밖으로 피하세요. 1~2레벨에는 (E)\'맹독 다트\'를 활용해 지속적인 마법 피해를 주며 거리를 유지하는 것이 중요해요. 초가스의 (E)\'날카로운 가시\'가 발동되지 않도록 평타 교환은 짧게 하고 뒤로 빠지세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 사용해 원뿔 범위 내의 적을 침묵시키려 하면 옆으로 이동해 피하세요. 초가스가 (E)\'날카로운 가시\'로 강화된 공격을 시도할 때 (Q)\'실명 다트\'를 맞혀 평타를 빗나가게 하세요. (W)\'신속한 이동\'을 켜서 초가스의 스킬 사거리에서 벗어나며 계속 견제하세요.', lv6: '초가스의 (R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 주므로 체력이 낮은 상태로 맞붙지 마세요. (R)\'유독성 함정\'을 초가스의 이동 경로에 미리 깔아두어 둔화와 피해를 입히는 것이 효율적이에요. 초가스가 (R)\'포식\'을 사용하려 할 때 (W)\'신속한 이동\'을 활용해 거리를 벌리며 정글러의 도움을 기다리세요.', item: '리안드리의 고통을 첫 코어로 선택하여 초가스의 높은 체력을 지속적으로 깎으세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\'을 통한 체력 회복 효과를 감소시키세요.' },
    '카밀': { lv1: '1~2레벨에는 (E)\'맹독 다트\'로 꾸준히 견제하며 거리를 유지하세요. 카밀의 (P)\'적응형 방어 체계\' 보호막이 생기면 평타 교환을 피하고 보호막이 사라진 뒤에 (Q)\'실명 다트\'를 맞춰주세요. (W)\'신속한 이동\'을 활용해 카밀의 (Q)\'정확성 프로토콜\' 사거리 밖에서 움직이며 압박하세요.', lv3: '카밀이 (W)\'전술적 휩쓸기\'를 사용하면 원뿔 바깥쪽 절반에 맞지 않도록 안쪽으로 붙거나 멀리 떨어지세요. 카밀이 (E)\'갈고리 발사\'로 벽을 타고 도약해 들어올 때는 (Q)\'실명 다트\'를 사용해 (Q)\'정확성 프로토콜\'의 추가 피해를 막아야 해요. (E)\'맹독 다트\'를 맞히며 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하지 못하도록 거리를 조절하세요.', lv6: '카밀의 (R)\'마법공학 최후통첩\'은 대상으로 지정할 수 없는 도약이라 막을 수 없으니, 갇힐 만한 자리에 (R)\'유독성 함정\'을 미리 깔아 카밀이 구역 안에서 밟게 만드세요. 궁극기 안에서 카밀이 강화 평타를 쓰려 할 때 (Q)\'실명 다트\'를 맞히면 피해를 크게 줄일 수 있어요. 카밀이 (E)\'갈고리 발사\'를 이용해 벽을 넘나들며 정글러와 협공할 수 있으니 라인 주변 시야 확보에 신경 쓰세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 마법 피해를 입히세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 카밀이 (W)\'전술적 휩쓸기\'를 통해 체력을 회복하는 것을 억제하세요.' },
    '카사딘': { lv1: '(Q)\'실명 다트\'를 사용하여 카사딘의 공격을 방해하며 거리를 유지해요. (E)\'맹독 다트\'의 지속 피해를 쌓으며 카사딘이 미니언을 챙길 때마다 견제하세요. 카사딘의 (Q)\'무의 구체\'로 생성되는 보호막을 고려하며 피해를 입히는 것이 중요해요.', lv3: '카사딘이 (E)\'힘의 파동\'을 사용하여 둔화를 걸며 다가오면 (Q)\'실명 다트\'를 맞춰 대응해요. (W)\'황천의 검\'을 사용한 카사딘의 기본 공격이 강력하므로 실명 효과를 활용해 피해를 줄이세요. (E)\'맹독 다트\'를 꾸준히 맞히며 체력을 깎아두는 것이 좋아요.', lv6: '카사딘이 (R)\'균열 이동\'을 사용하여 순식간에 거리를 좁히는 것을 항상 조심하세요. 카사딘이 이동할 경로에 (R)\'유독성 함정\'을 미리 설치하여 진입을 방해하고 피해를 입히세요. 라인을 당겨서 관리하며 정글러의 개입을 기다리는 것이 좋아요.', item: '헤르메스의 발걸음과 리안드리의 고통을 구매해요. 카사딘의 마법 피해를 견디기 위해 헤르메스의 발걸음을 가고 지속적인 피해를 위해 리안드리의 고통을 선택해요.', spell: '점멸과 점화를 선택해요. 카사딘의 (R)\'균열 이동\'에 대응하기 위해 점멸을 사용하고 점화로 마무리 피해를 더하세요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'의 사거리가 더 길기 때문에 무리하게 다가가지 마세요. (E)\'맹독 다트\'를 활용해 짧은 딜교환을 시도하고 빠르게 거리를 벌리세요. (W)\'신속한 이동\'을 켜서 상대의 스킬 범위에서 벗어나며 체력을 관리해요.', lv3: '상대의 (Q)\'맹독 폭발\'을 피하며 (Q)\'실명 다트\'로 견제하고 거리를 조절하세요. (E)\'맹독 다트\'의 중독 피해를 입히면서 상대의 체력을 갉아먹는 구도를 유지해요. (E)\'쌍독니\'의 피해를 감당해야 하므로 불필요한 진입은 자제하세요.', lv6: '(R)\'석화의 응시\'를 사용할 때 반드시 등을 지고 움직여 기절을 피하고 둔화만 받으세요. 상대의 진입 경로에 (R)\'유독성 함정\'을 설치하여 움직임을 제한하고 킬각을 잡으세요. 정글러가 올 때 버섯으로 길목을 차단하여 안전하게 대처해요.', item: '헤르메스의 발걸음과 내셔의 이빨을 선택하세요. 마법 저항력과 강인함으로 군중 제어 시간을 줄이고 공격 속도와 주문력을 높여 피해량을 늘려요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (E)\'쌍독니\'를 통한 상대의 체력 회복을 방해하며 싸우세요.' },
    '케넨': { lv1: '케넨이 (Q)\'천둥의 표창\'을 던져 표식을 남기니 미니언 뒤에 숨어 피해를 최소화하세요. (Q)\'실명 다트\'를 사용하여 케넨의 공격을 방해하면서 (E)\'맹독 다트\'가 묻은 평타로 견제하는 것이 좋아요. 케넨이 (P)\'폭풍의 표식\'을 쌓지 못하도록 거리를 유지하는 데 집중하세요.', lv3: '케넨이 (E)\'번개 질주\'로 들어오면 부딪힐 때 (P)\'폭풍의 표식\'이 쌓이니 (W)\'신속한 이동\'으로 거리를 벌리고, 이후 평타를 치려 할 때 (Q)\'실명 다트\'를 맞히세요. (W)\'전류 방출\'을 사용해 표식을 쌓는 순간에는 (W)\'신속한 이동\'을 활용해 거리를 벌려야 해요. 케넨의 (E)\'번개 질주\'가 빠진 타이밍에 (E)\'맹독 다트\'를 활용한 평타 교환을 시도하세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜고 들어오면 광역 피해가 상당하니 주의해야 해요. 진입하는 경로에 (R)\'유독성 함정\'을 설치해 케넨의 움직임을 둔화시키고 피해를 주세요. 케넨이 궁극기를 사용한 직후 (Q)\'실명 다트\'를 맞춰 교전 상황을 주도하세요.', item: '첫 코어로 리안드리의 고통을 선택해 지속적인 마법 피해를 입히세요. 신발은 케넨의 마법 피해를 견디고 (P)\'폭풍의 표식\' 기절 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\' 기절은 정화로 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'의 효과를 받기 전이라 초반 구간이 가장 약해요. (Q)\'실명 다트\'를 사용하여 지속적으로 견제하며 케일의 체력을 미리 깎아 두세요. (Q)\'광휘의 일격\'의 사거리를 조심하며 거리를 유지하는 것이 중요해요.', lv3: '케일이 (E)\'화염주문검\'을 사용해 사거리가 늘어나면 (Q)\'실명 다트\'를 맞춰 평타 공격을 방해하세요. (W)\'천상의 축복\'으로 체력을 회복할 수 있으니 딜교환 이후에는 빠르게 거리를 벌려야 해요. (E)\'맹독 다트\'를 묻힌 상태에서 평타를 꾸준히 섞어 피해를 누적시키세요.', lv6: '케일이 (R)\'신성한 심판\'을 쓰면 무적 상태가 되어 피해를 줄 수 없으니 주의하세요. 궁극기가 빠진 것을 확인한 뒤에 (R)\'유독성 함정\'을 길목에 깔아 케일의 움직임을 제한하세요. (Q)\'실명 다트\'와 (E)\'맹독 다트\'를 활용해 피해를 입히며 정글러와 함께 압박을 이어가세요.', item: '첫 코어로 리안드리의 고통을 선택하여 지속적인 피해를 입히세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신어주세요.', spell: '점멸과 점화를 추천해요. 케일이 강해지기 전에 점화로 킬을 따내어 성장을 억제해야 해요.' },
    '코그모': { lv1: '1~2레벨에는 (E)\'맹독 다트\'를 활용해 조금씩 체력을 깎으세요. 코그모의 (Q)\'부식성 침\'은 처음 맞은 대상에게만 피해를 주니 미니언 뒤에 숨어 피해를 최소화하세요. 무리하게 다가가기보다 거리를 유지하며 견제하세요.', lv3: '코그모가 (W)\'생체마법 폭격\'으로 사거리를 늘려 공격하면 즉시 (Q)\'실명 다트\'를 던져 기본 공격을 무력화하세요. (E)\'공허의 분비물\' 흔적 위에 있으면 둔화되니 (W)\'신속한 이동\'을 켜고 빠르게 벗어나세요. 상대의 스킬이 빠진 틈을 타 짧게 딜교환을 시도하세요.', lv6: '(R)\'유독성 함정\'을 상대의 예상 이동 경로에 설치해 둔화시킨 뒤 공격하세요. 체력이 낮을 때 (R)\'살아있는 곡사포\'에 맞으면 피해가 매우 크니 주의하며 체력을 관리하세요. 정글러가 올 때를 대비해 길목에 (R)\'유독성 함정\'을 깔아 위치를 파악하세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 헤르메스의 발걸음은 마법 저항력으로 피해를 줄이고 강인함으로 (E)\'공허의 분비물\' 둔화 시간을 줄여줘요. 내셔의 이빨은 주문력과 공격 속도를 높여 (E)\'맹독 다트\'의 피해량을 올려줘요.', spell: '점멸과 점화를 추천해요. 코그모는 체력을 회복하는 수단이 없으니 점화의 고정 피해를 이용해 킬 결정력을 높이세요.' },
    '코르키': { lv1: '(Q)\'실명 다트\'로 코르키를 견제하며 거리를 유지하세요. 코르키의 (Q)\'인광탄\'은 범위 피해를 주고 맞은 지역을 드러내니 떨어지는 지점에서 벗어나 움직이세요. (W)\'신속한 이동\'을 사용하여 상대의 공격을 피하며 파밍에 집중하세요.', lv3: '코르키가 (E)\'개틀링 건\'을 사용하기 전에 (Q)\'실명 다트\'를 맞춰 평타를 방해하세요. (E)\'맹독 다트\'를 적중시켜 지속적인 피해를 입히며 딜교환을 시도하세요. (W)\'신속한 이동\'을 활용해 코르키의 (W)\'발키리\' 이동 경로를 주의하며 거리를 조절하세요.', lv6: '(R)\'유독성 함정\'을 코르키의 예상 경로에 설치하여 둔화를 유도하세요. 코르키가 (R)\'미사일 폭격\'을 사용할 때는 긴 사거리를 조심하며 라인을 관리하세요. 상대가 함정을 밟아 움직임이 느려지면 (Q)\'실명 다트\'를 사용하여 킬각을 보세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 리안드리의 고통으로 지속적인 화상을 입히고 헤르메스의 발걸음으로 마법 저항력을 얻으세요.', spell: '점멸과 점화를 추천해요. 점화는 상대의 체력을 낮게 유지하여 마무리 피해를 입히는 데 도움을 줘요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 남은 상태에서 첫 평타가 강력하니 거리를 유지하며 (E)\'맹독 다트\'로 지속적인 피해를 입히세요. 수풀 속에서 (P)\'유격 전투\' 상태를 활용해 시야를 숨기고 퀸의 접근을 까다롭게 만드세요. 1~2레벨 구간에는 무리한 딜교환보다는 미니언을 챙기며 버티는 것이 좋아요.', lv3: '퀸이 (E)\'공중제비\'를 사용하여 들어오는 타이밍을 기다렸다가 (Q)\'실명 다트\'를 맞춰 딜교환에서 이득을 보세요. 퀸의 (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 주의하고, 퀸이 (E)\'공중제비\'를 쓰고 물러난 뒤에 (E)\'맹독 다트\'를 활용해 독 피해를 입히세요. 퀸의 진입 스킬이 빠진 상태를 노려 견제하는 것이 좋아요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 빠르게 이동하면 예상 경로에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추세요. 퀸의 (R)\'후방 지원\' 이후 착지 지점을 예측해 버섯을 깔아두면 퀸의 진입을 효과적으로 막을 수 있어요. 퀸이 로밍을 시도할 때 라인을 빠르게 밀어 (R)\'유독성 함정\'으로 적의 진입을 경계하며 성장하세요.', item: '리안드리의 고통을 첫 코어로 선택해 (E)\'맹독 다트\'의 지속 피해를 높이세요. 신발은 퀸의 기본 공격 피해를 줄이기 위해 판금 장화를 구매하세요.', spell: '점멸과 점화를 추천해요. 퀸이 (E)\'공중제비\'로 들어올 때 점멸로 대응하거나 (R)\'유독성 함정\' 근처에서 점화로 마무리하기 좋아요.' },
    '크산테': { lv1: '(Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 맞히면 기절시키며 끌어당기니 항상 거리를 유지하세요. (E)\'맹독 다트\'로 계속 견제하며 상대의 체력을 깎는 것이 중요해요. (P)\'불굴의 본능\' 표식이 남았을 때 (Q)\'실명 다트\'를 사용하면 기본 공격 추가 피해를 막을 수 있어요.', lv3: '(E)\'발놀림\'으로 돌진해 들어오면 (W)\'신속한 이동\'을 사용해 빠르게 거리를 벌리세요. (W)\'길을 여는 자\'는 저지 불가 상태로 돌진하며 기절시키니 충전 동작이 보이면 즉시 옆으로 피하세요. 상대의 돌진기가 모두 빠진 뒤에 (E)\'맹독 다트\'로 짧게 딜교환을 하세요.', lv6: '(R)\'총공세\'를 쓰면 상대 방어력이 줄어드니 (R)\'유독성 함정\'을 깔아 이동 속도를 늦추고 피해를 입히세요. 하지만 총공세 상태의 크산테는 공격력이 강해지므로 정면 대결은 피해야 해요. 벽 근처에 있으면 (R)\'총공세\'로 밀려나 위험할 수 있으니 탁 트인 공간에서 싸우세요.', item: '첫 코어는 스태틱의 단검으로 가서 연쇄 번개로 라인 정리와 교환 피해를 함께 챙기세요. 신발은 판금 장화를 선택해 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 크산테는 체력이 많아 처치가 어려우니 순간이동으로 라인 손해를 줄이세요.' },
    '클레드': { lv1: '클레드가 (Q)\'덫날리기\'로 붙잡아 끌어당기려 하면 거리를 벌리며 (E)\'맹독 다트\'로 지속적인 피해를 입히세요. (Q)\'실명 다트\'를 사용해 클레드의 기본 공격을 차단하면서 첫 웨이브를 받아내는 것이 중요해요. (W)\'신속한 이동\'을 사용해 클레드가 접근하기 어렵게 거리를 유지하세요.', lv3: '클레드가 (W)\'버럭버럭\'을 사용하여 공격 속도가 빨라지는 동안에는 (Q)\'실명 다트\'를 맞춰 평타를 못 쓰게 방해하세요. (E)\'이랴!\'로 돌진해 올 때는 (W)\'신속한 이동\'으로 거리 조절을 하고 (E)\'맹독 다트\'를 맞히며 딜교환을 하세요. 클레드의 (Q)\'덫날리기\'가 빠진 타이밍을 노려 적극적으로 공격하세요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'을 사용하여 돌진할 경로에 (R)\'유독성 함정\'을 미리 깔아두어 진입을 방해하세요. 클레드가 스칼에서 내려와 피해량이 줄어든 시점을 노려 (Q)\'실명 다트\'를 맞히며 집중 공격하세요. 갱킹을 대비해 주요 길목에 버섯을 설치하며 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 피해를 입히세요. 신발은 기본 공격으로 받는 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 클레드가 스칼에서 내렸을 때 남은 체력을 빠르게 깎기 위해 점화를 사용하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 피해를 주고 체력을 회복하며 (P)\'절대 미각\' 중첩을 쌓아요. (Q)\'혀 채찍\'은 처음 맞는 유닛을 공격하니 미니언 뒤에 서서 피하세요. (Q)\'실명 다트\'로 견제하며 (P)\'절대 미각\' 중첩이 쌓이지 않게 거리를 유지하세요.', lv3: '탐 켄치의 (W)\'심연 잠수\'가 나타날 위치가 보이면 즉시 범위 밖으로 움직이세요. (E)\'두꺼운 피부\'로 비축한 피해가 보호막으로 바뀔 수 있으니 보호막이 사라진 후에 (E)\'맹독 다트\'를 맞히는 게 좋아요. (Q)\'실명 다트\'를 사용하여 탐 켄치의 기본 공격을 방해하며 딜교환을 하세요.', lv6: '(P)\'절대 미각\' 중첩이 쌓인 상태에서 (R)\'집어삼키기\'에 먹히면 큰 피해를 입으니 주의하세요. (R)\'유독성 함정\'을 퇴로에 깔아 탐 켄치가 다가오지 못하게 둔화시키고 거리를 벌리세요. (W)\'신속한 이동\'을 활용해 탐 켄치의 접근을 피하며 라인을 관리하세요.', item: '리안드리의 고통을 코어로 선택해 체력이 높은 탐 켄치에게 지속적인 피해를 주세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'을 통한 체력 회복을 줄이세요.' },
    '트런들': { lv1: '(E)\'맹독 다트\'로 계속 견제하며 거리를 유지하세요. 트런들이 (Q)\'깨물기\'를 쓰며 다가오면 (W)\'신속한 이동\'을 사용해 빠르게 거리를 벌리세요. (P)\'헌납\'으로 인해 주변 유닛이 죽을 때 체력을 회복하니 미니언이 많은 곳에서 교환하지 마세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 깔면 공격 속도가 빨라지니 영역 밖으로 나가서 교환하세요. 트런들의 (Q)\'깨물기\' 강화 평타 타이밍에 (Q)\'실명 다트\'를 맞혀 피해와 공격력 흡수를 막으세요. (E)\'얼음 기둥\'으로 퇴로를 막거나 밀어낼 수 있으니 벽에 갇히지 않게 주의하며 거리를 조절하세요.', lv6: '트런들이 (R)\'진압\'을 맞히면 체력과 방어력, 마법 저항력을 즉시 훔쳐 단단해지니 효과가 유지되는 동안은 거리를 벌려 싸움을 피하세요. 상대의 이동 경로에 (R)\'유독성 함정\'을 미리 깔아 둔화시키며 정글러의 갱킹에 대비하세요. (E)\'얼음 기둥\'에 막혀 도망칠 수 없는 상황이 되면 (W)\'신속한 이동\'을 켜고 빠르게 빠져나가세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 트런들에게 지속적인 마법 피해를 주세요. 신발은 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트런들은 (P)\'헌납\'과 (W)\'얼음 왕국\'으로 체력을 많이 회복하니 점화의 치유 감소로 이를 억제하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 쌓아 치명타를 노리니 평타 거리를 유지하며 (E)\'맹독 다트\'로 계속 괴롭히세요. 평타를 주고받을수록 분노가 쌓여 (Q)\'피의 갈망\' 회복량이 커지니 근접 교환을 피하며 견제하세요. 무리하게 들어가기보다 상대가 다가올 때 뒤로 빠지며 견제하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 돌진해 들어오는 순간에 맞춰 (Q)\'실명 다트\'를 사용해 평타 딜로스를 유도하세요. (W)\'조롱의 외침\'에 맞았을 때 곧바로 등을 돌려 도망치면 둔화가 걸리니 (W)\'신속한 이동\'을 켜고 대각선 방향으로 움직이며 거리를 벌리세요. 상대의 돌진기가 빠진 타이밍에 (E)\'맹독 다트\'를 섞어 짧은 딜교환을 반복하세요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 켜면 잠시 동안 죽지 않으니, 이때는 딜을 쏟기보다 (R)\'유독성 함정\'을 발밑에 깔아 둔화시키며 시간을 버티세요. 궁극기 지속시간이 끝나는 시점에 (Q)\'실명 다트\'와 평타를 집중해 마무리하는 것이 효율적이에요. 라인을 당겨두고 정글러가 오기 좋은 길목에 (R)\'유독성 함정\'을 배치해 진입 경로를 제한하세요.', item: '내셔의 이빨을 코어 아이템으로 선택해 주문력과 공격 속도를 높여 지속 피해를 강화하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 트린다미어는 (Q)\'피의 갈망\'을 통해 체력을 회복하므로 점화의 치유 감소 효과가 매우 중요해요.' },
    '판테온': { lv1: '(Q)\'혜성의 창\' 사거리보다 내 사거리가 더 기니 (E)\'맹독 다트\'로 계속 견제하세요. 판테온이 (P)\'필멸자의 의지\'를 쌓아 강화된 공격을 하려 하면 거리를 벌리며 대응하세요. 1~2레벨에는 무리하게 붙지 말고 평타 견제에 집중해요.', lv3: '판테온이 (W)\'방호의 도약\'으로 뛰어들면 기절에 걸려 스킬을 쓸 수 없으니 도약 전에 거리를 벌리세요. (E)\'방패 돌격\'을 사용하면 정면 공격이 면역이니 억지로 때리지 말고 옆으로 피하세요. (W)\'신속한 이동\'을 켜서 판테온의 진입 거리 밖에서 계속 괴롭히세요.', lv6: '판테온이 (R)\'거대 유성\'으로 도약하면 떨어지는 위치에 (R)\'유독성 함정\'을 설치해 이동 속도를 늦추고 피해를 주세요. (W)\'방호의 도약\'이 빠진 타이밍에 (E)\'맹독 다트\'와 평타로 계속 압박하면 체력을 크게 깎을 수 있어요. 유성으로 인한 갑작스러운 합류가 잦으니 라인을 너무 밀지 말고 주의하세요.', item: '내셔의 이빨과 판금 장화를 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 내셔의 이빨은 공격 속도와 주문력을 높여 줘요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\' 기절을 정화로 빠르게 풀 수 있어요.' },
    '피들스틱': { lv1: '1~2레벨 구간에는 (E)\'맹독 다트\'를 활용해 지속적으로 체력을 깎으며 거리를 유지하세요. 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용해 기습하지 못하도록 미니언 근처에서 주의 깊게 움직이세요.', lv3: '3레벨 이후에는 (E)\'수확\'의 중심 범위에 맞으면 침묵 상태가 되어 스킬을 쓸 수 없으니 무빙으로 피하세요. 상대가 (W)\'풍작\'을 사용해 체력을 회복하려 하면 (W)\'신속한 이동\'을 켜고 빠르게 거리 조절을 하며 피해를 입히세요.', lv6: '6레벨 이후에는 피들스틱이 (R)\'까마귀 폭풍\'으로 진입할 예상 경로에 (R)\'유독성 함정\'을 미리 설치해 둔화시키세요. 상대가 궁극기로 들어온 직후에는 거리 조절에 집중하며 정글러의 백업을 기다리는 것이 좋아요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하고 내셔의 이빨은 주문력과 공격 속도를 높여줘요.', spell: '점멸과 점화를 추천해요. 점멸로 갑작스러운 진입에 대응하고 점화로 상대의 체력 회복 효과를 감소시키며 빠르게 처치하세요.' },
    '피오라': { lv1: '1~2레벨에는 (E)\'맹독 다트\'로 계속 견제하며 피오라의 체력을 깎으세요. 피오라가 (Q)\'찌르기\'로 빠르게 진입해 (P)\'치명적인 검무\'의 급소를 찌르지 못하게 계속 움직여야 해요. (W)\'신속한 이동\'을 켜서 거리 조절을 하며 상대가 다가오지 못하게 압박하세요.', lv3: '(W)\'응수\'가 켜진 동안에는 모든 공격과 이동 불가 효과가 막히니 (Q)\'실명 다트\'를 쓰지 말고 뒤로 물러나세요. (W)\'응수\'가 끝난 직후에 (Q)\'실명 다트\'를 맞춰 피오라의 (E)\'대가의 검술\' 평타 피해를 무력화하는 것이 중요해요. (W)\'신속한 이동\'으로 (Q)\'찌르기\' 돌진 거리를 벗어나며 일방적인 딜교환을 유도하세요.', lv6: '(R)\'대결투\'가 시작되면 급소가 네 군데 모두 드러나니 무빙으로 급소 가격을 최대한 피하세요. 피오라가 다가오는 경로에 (R)\'유독성 함정\'을 미리 깔아 둔화시키고 접근 속도를 늦춰야 해요. 정글러가 오기 쉬운 구도이니 (R)\'유독성 함정\'으로 시야를 확보하고 라인을 당겨 아군 포탑 근처에서 유지하세요.', item: '내셔의 이빨을 첫 코어로 가서 주문력과 공격 속도를 챙겨 견제력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'와 (R)\'대결투\'로 체력을 회복하는 것을 점화의 치유 감소로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 설치하면 포탑의 공격 범위 안에서 미니언을 챙기지 마세요. (W)\'신속한 이동\'을 사용하여 (W)\'마법공학 초소형 로켓\'의 사선을 피하며 (E)\'맹독 다트\'로 견제하세요. 포탑 근처에서 싸우기보다 거리 조절에 집중하며 미니언을 받아먹어야 해요.', lv3: '하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\' 중앙에 맞으면 기절하니 수류탄이 떨어지는 위치를 잘 피하세요. 수류탄이 빠진 타이밍에 (Q)\'실명 다트\'를 맞히고 (E)\'맹독 다트\'로 피해를 누적시키며 딜교환을 하세요. (W)\'마법공학 초소형 로켓\'이 날아올 때도 무빙으로 피해를 최소화해야 해요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용하여 강화된 스킬을 쓰면 피해가 매우 크니 조심하세요. 하이머딩거의 이동 경로에 (R)\'유독성 함정\'을 설치하여 이동 속도를 늦추며 압박하세요. 포탑이 없는 틈을 타서 싸움을 걸거나 (R)\'유독성 함정\'으로 길목을 차단하며 정글러의 도움을 기다리세요.', item: '첫 코어로 리안드리의 고통을 올려 지속적인 마법 피해를 입히세요. 신발은 하이머딩거의 마법 피해와 (E)\'CH-2 전자폭풍 수류탄\' 기절 지속시간을 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 하이머딩거의 포탑을 피해 진입하거나 체력이 낮은 하이머딩거를 확실히 마무리하기 위해서예요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_teemo);
if (typeof module !== 'undefined') module.exports = top_teemo;
